import { Question, CurveDiagramConfig } from "@/lib/types";

/**
 * Year 2 — Numerical Methods § 10.3 Sketching Iterations
 * Ref: y2nm3
 * 70 questions on sketching staircase/cobweb diagrams for the fixed-point
 * iteration x_{n+1} = g(x_n): drawing y = g(x) with y = x, tracking the
 * iterate path, and using the slope of g at the fixed point to classify
 * convergence (staircase vs cobweb) or divergence.
 */

// Build a cobweb/staircase diagram for the iteration x_{n+1} = g(x_n).
// Produces the curve y = g(x), the line y = x, and the iterate path.
function cobwebDiagram(
  g: (x: number) => number,
  xRange: [number, number],
  yRange: [number, number],
  x0: number,
  steps: number,
  opts: { curveLabel?: string } = {},
): CurveDiagramConfig {
  const N = 60;
  const curve: Array<[number, number]> = [];
  const [xMin, xMax] = xRange;
  for (let i = 0; i <= N; i++) {
    const x = xMin + ((xMax - xMin) * i) / N;
    curve.push([x, g(x)]);
  }
  const pathPoints: Array<[number, number]> = [];
  let x = x0;
  pathPoints.push([x, 0]);
  pathPoints.push([x, g(x)]);
  for (let i = 0; i < steps; i++) {
    const yNext = g(x);
    pathPoints.push([yNext, yNext]);
    pathPoints.push([yNext, g(yNext)]);
    x = yNext;
  }
  const lines = [] as NonNullable<CurveDiagramConfig["lines"]>;
  lines.push({ from: [xMin, xMin], to: [xMax, xMax], color: "#64748b", dashed: true });
  for (let i = 0; i < pathPoints.length - 1; i++) {
    lines.push({ from: pathPoints[i]!, to: pathPoints[i + 1]!, color: "#dc2626" });
  }
  return {
    xMin, xMax, yMin: yRange[0], yMax: yRange[1], hideAxes: false,
    curves: [{
      points: curve, color: "#1d4ed8", width: 2,
      label: opts.curveLabel ?? "y = g(x)",
      labelAt: [xMax - (xMax - xMin) * 0.25, g(xMax - (xMax - xMin) * 0.25)],
    }],
    lines,
  };
}

export const questions: Question[] = [
  { id: "y2nm3-001", topicRef: "y2nm3", topicTitle: "Sketching Iteration 01", difficulty: "Foundation", questionText: "Describe, in your own words, what a staircase diagram represents for the iteration \\(x_{n+1} = g(x_{n})\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the axes by plotting both \\(y = g(x)\\) and the auxiliary line \\(y = x\\) on the same diagram.", workingLatex: "", explanation: "The line \\(y = x\\) acts as a 'feedback channel' that converts an output \\(g(x_{n})\\) back into the next input \\(x_{n+1}\\). The fixed point sits where the curve crosses this line." }, { stepNumber: 2, description: "Starting from \\(x_{0}\\) on the \\(x\\)-axis, draw a vertical segment up to the curve to read off \\(x_{1} = g(x_{0})\\).", workingLatex: "x_{1} = g(x_{0})", explanation: "The height of the curve above \\(x_{0}\\) is the next iterate." }, { stepNumber: 3, description: "Draw a horizontal segment from \\(\\left(x_{0}, x_{1}\\right)\\) across to \\(y = x\\), arriving at \\(\\left(x_{1}, x_{1}\\right)\\).", workingLatex: "", explanation: "This 'feeds' the output \\(x_{1}\\) back to the \\(x\\)-axis ready for the next vertical step." }, { stepNumber: 4, description: "Repeat: vertical to \\(y = g(x)\\), horizontal to \\(y = x\\). On a staircase the segments form rising or falling steps that stay on one side of the fixed point \\(\\alpha\\).", workingLatex: "", explanation: "Staircases occur when \\(0 < g'(\\alpha) < 1\\) (converging) or \\(g'(\\alpha) > 1\\) (diverging). Successive iterates approach (or recede from) \\(\\alpha\\) monotonically.", diagram: cobwebDiagram((x) => 0.5 * x + 0.5, [0, 1.5], [0, 1.5], 0, 4) }, { stepNumber: 5, description: "Conclude with a sentence summarising the picture.", workingLatex: "", explanation: "Each step of the iteration is recorded geometrically; the long-run behaviour is visible at a glance." } ], finalAnswer: "A staircase diagram visualises each iteration as a vertical step to \\(y = g(x)\\) followed by a horizontal step to \\(y = x\\), producing a monotone 'stair' that climbs (or descends) toward, or away from, the fixed point." } },
  { id: "y2nm3-002", topicRef: "y2nm3", topicTitle: "Sketching Iteration 02", difficulty: "Foundation", questionText: "State the difference between a staircase diagram and a cobweb diagram.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "Both diagrams use the same construction (vertical to \\(y = g(x)\\), horizontal to \\(y = x\\)), but the sign of \\(g'(\\alpha)\\) distinguishes them.", workingLatex: "", explanation: "The slope of the curve at the fixed point is what determines whether iterates approach \\(\\alpha\\) from one side or alternate." }, { stepNumber: 2, description: "Staircase: \\(g'(\\alpha) > 0\\). All iterates stay on one side of \\(\\alpha\\) (or pass through and stay on the other side once).", workingLatex: "0 < g'(\\alpha) < 1\\ \\Rightarrow\\ \\text{converging staircase}", explanation: "Monotone approach — the picture resembles a flight of stairs." }, { stepNumber: 3, description: "Cobweb: \\(g'(\\alpha) < 0\\). Iterates alternate either side of \\(\\alpha\\), producing a rectangular spiral.", workingLatex: "-1 < g'(\\alpha) < 0\\ \\Rightarrow\\ \\text{converging cobweb}", explanation: "Each iterate overshoots \\(\\alpha\\) and then under-shoots, looking like a web of crossing horizontals and verticals.", diagram: cobwebDiagram((x) => -0.5 * x + 1.5, [0, 2], [0, 2], 0.2, 5) }, { stepNumber: 4, description: "In both cases convergence requires \\(|g'(\\alpha)| < 1\\); if \\(|g'(\\alpha)| > 1\\) the same pattern occurs but moving outwards (diverging).", workingLatex: "", explanation: "" } ], finalAnswer: "A staircase has \\(g'(\\alpha) > 0\\) and gives a monotone step pattern; a cobweb has \\(g'(\\alpha) < 0\\) and gives an oscillating spiral pattern." } },
  { id: "y2nm3-003", topicRef: "y2nm3", topicTitle: "Sketching Iteration 03", difficulty: "Foundation", questionText: "State the condition on \\(g'(\\alpha)\\) for the iteration \\(x_{n+1} = g(x_{n})\\) to converge to the fixed point \\(\\alpha\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "Near the fixed point linearise \\(g\\) by Taylor expansion: \\(g(x) \\approx \\alpha + g'(\\alpha)(x - \\alpha)\\).", workingLatex: "", explanation: "So the error \\(e_{n} = x_{n} - \\alpha\\) satisfies \\(e_{n+1} \\approx g'(\\alpha)\\, e_{n}\\)." }, { stepNumber: 2, description: "Iterating this linear approximation gives \\(e_{n} \\approx [g'(\\alpha)]^{n}\\, e_{0}\\).", workingLatex: "e_{n} \\approx \\left(g'(\\alpha)\\right)^{n} e_{0}", explanation: "The geometric factor controls whether the error shrinks or grows." }, { stepNumber: 3, description: "For convergence we need \\(\\left(g'(\\alpha)\\right)^{n} \\to 0\\), which requires the magnitude of the multiplier to be strictly less than 1.", workingLatex: "\\left|g'(\\alpha)\\right| < 1", explanation: "" }, { stepNumber: 4, description: "The picture on a sketch: the curve must be less steep than the line \\(y = x\\) at the intersection point.", workingLatex: "", explanation: "Steeper than \\(y = x\\) gives divergence; less steep gives convergence.", diagram: cobwebDiagram((x) => 0.5 * x + 0.5, [0, 1.5], [0, 1.5], 0, 4) } ], finalAnswer: "\\(\\left|g'(\\alpha)\\right| < 1\\)." } },
  { id: "y2nm3-004", topicRef: "y2nm3", topicTitle: "Sketching Iteration 04", difficulty: "Foundation", questionText: "Where on a sketch does the fixed point \\(\\alpha\\) of \\(x_{n+1} = g(x_{n})\\) appear?", marks: 1, examStyle: false, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "Define a fixed point: it is a value \\(\\alpha\\) that the iteration leaves unchanged.", workingLatex: "g(\\alpha) = \\alpha", explanation: "If \\(x_{n} = \\alpha\\) then \\(x_{n+1} = g(\\alpha) = \\alpha\\) as well." }, { stepNumber: 2, description: "Geometrically the equation \\(g(\\alpha) = \\alpha\\) says the curve \\(y = g(x)\\) and the line \\(y = x\\) take the same value at \\(x = \\alpha\\).", workingLatex: "", explanation: "Therefore the point \\(\\left(\\alpha, \\alpha\\right)\\) lies on both graphs." }, { stepNumber: 3, description: "On a sketch this corresponds to the intersection of the two graphs.", workingLatex: "", explanation: "Reading off the \\(x\\)-coordinate of that intersection gives \\(\\alpha\\).", diagram: cobwebDiagram((x) => 0.4 * x + 0.6, [0, 1.5], [0, 1.5], 0.1, 4) } ], finalAnswer: "At the intersection of \\(y = g(x)\\) with the line \\(y = x\\)." } },
  { id: "y2nm3-005", topicRef: "y2nm3", topicTitle: "Sketching Iteration 05", difficulty: "Foundation", questionText: "Sketch the staircase diagram for \\(x_{n+1} = \\tfrac{x_{n} + 3}{4}\\) starting from \\(x_{0} = 0\\), and state the fixed point.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase", "linear"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration: \\(g(x) = \\displaystyle\\frac{x + 3}{4}\\), with \\(x_{0} = 0\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Find the fixed point from \\(\\alpha = g(\\alpha)\\).", workingLatex: "\\alpha = \\frac{\\alpha + 3}{4}\\ \\Rightarrow\\ 4\\alpha = \\alpha + 3\\ \\Rightarrow\\ \\alpha = 1", explanation: "" }, { stepNumber: 3, description: "Compute the slope of \\(g\\) at \\(\\alpha\\).", workingLatex: "g'(x) = \\frac{1}{4},\\quad g'(1) = \\frac{1}{4}", explanation: "\\(0 < g'(\\alpha) < 1\\) so the diagram is a converging staircase." }, { stepNumber: 4, description: "Construct iterates explicitly to confirm.", workingLatex: "x_{1} = \\tfrac{3}{4} = 0.75,\\ x_{2} = \\tfrac{15}{16} = 0.9375,\\ x_{3} \\approx 0.9844", explanation: "Each iterate is one-quarter of the way from the previous to \\(\\alpha = 1\\)." }, { stepNumber: 5, description: "Describe the staircase: from \\(\\left(0, 0\\right)\\) go up to \\(\\left(0, 0.75\\right)\\) on the curve, across to \\(\\left(0.75, 0.75\\right)\\) on \\(y = x\\), then up to the curve again — each step is shorter than the previous.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => (x + 3) / 4, [-0.2, 1.4], [-0.2, 1.4], 0, 4) }, { stepNumber: 6, description: "Conclude: the staircase climbs monotonically from below toward \\(\\alpha = 1\\).", workingLatex: "", explanation: "Since \\(\\left|g'(\\alpha)\\right| = \\tfrac{1}{4} < 1\\), convergence is guaranteed." } ], finalAnswer: "Monotone staircase converging to \\(\\alpha = 1\\)." } },
  { id: "y2nm3-006", topicRef: "y2nm3", topicTitle: "Sketching Iteration 06", difficulty: "Foundation", questionText: "Sketch the staircase diagram for \\(x_{n+1} = 0.6 x_{n} + 1\\) starting from \\(x_{0} = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase", "linear"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = 0.6 x + 1\\) and \\(x_{0} = 0\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Solve for the fixed point.", workingLatex: "\\alpha = 0.6\\alpha + 1\\ \\Rightarrow\\ 0.4\\alpha = 1\\ \\Rightarrow\\ \\alpha = \\frac{5}{2} = 2.5", explanation: "" }, { stepNumber: 3, description: "The slope of \\(g\\) is constant: \\(g'(x) = 0.6\\).", workingLatex: "0 < g'(\\alpha) = 0.6 < 1", explanation: "Converging staircase pattern." }, { stepNumber: 4, description: "Compute a few iterates.", workingLatex: "x_{1} = 1,\\ x_{2} = 1.6,\\ x_{3} = 1.96,\\ x_{4} = 2.176", explanation: "Each step closes about 40% of the remaining gap to \\(\\alpha\\)." }, { stepNumber: 5, description: "On the diagram each iterate is a vertical move to the curve followed by a horizontal move to \\(y = x\\); the staircase climbs from \\(0\\) toward \\(2.5\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 0.6 * x + 1, [0, 3], [0, 3], 0, 5) }, { stepNumber: 6, description: "Conclusion: monotone staircase converging from below to \\(\\alpha = 2.5\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase converging to \\(\\alpha = 2.5\\)." } },
  { id: "y2nm3-007", topicRef: "y2nm3", topicTitle: "Sketching Iteration 07", difficulty: "Foundation", questionText: "Sketch the staircase diagram for \\(x_{n+1} = 0.8 x_{n} + 1\\) starting from \\(x_{0} = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase", "linear"], workedSolution: { steps: [ { stepNumber: 1, description: "Start with \\(g(x) = 0.8x + 1\\), \\(x_{0} = 0\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Find the fixed point.", workingLatex: "\\alpha = 0.8\\alpha + 1\\ \\Rightarrow\\ 0.2\\alpha = 1\\ \\Rightarrow\\ \\alpha = 5", explanation: "" }, { stepNumber: 3, description: "Slope at \\(\\alpha\\): \\(g'(x) = 0.8\\); since \\(0 < 0.8 < 1\\) the iteration converges, but slowly (each step removes only \\(20\\%\\) of the error).", workingLatex: "", explanation: "" }, { stepNumber: 4, description: "Compute iterates.", workingLatex: "x_{1} = 1,\\ x_{2} = 1.8,\\ x_{3} = 2.44,\\ x_{4} \\approx 2.952,\\ x_{5} \\approx 3.362", explanation: "After five iterations we are still well short of \\(5\\) — the staircase steps are visibly shrinking but slowly." }, { stepNumber: 5, description: "Construct the staircase: vertical from \\(\\left(x_{n}, 0\\right)\\) up to \\(\\left(x_{n}, g(x_{n})\\right)\\), horizontal across to \\(\\left(x_{n+1}, x_{n+1}\\right)\\), then repeat.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 0.8 * x + 1, [0, 6], [0, 6], 0, 5) }, { stepNumber: 6, description: "Conclude: monotone staircase climbing slowly from \\(0\\) toward \\(\\alpha = 5\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Slow monotone staircase converging to \\(\\alpha = 5\\)." } },
  { id: "y2nm3-008", topicRef: "y2nm3", topicTitle: "Sketching Iteration 08", difficulty: "Foundation", questionText: "Sketch the cobweb diagram for \\(x_{n+1} = -\\tfrac{1}{2} x_{n} + 1\\) starting from \\(x_{0} = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb", "linear"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration: \\(g(x) = -\\displaystyle\\frac{x}{2} + 1\\) with \\(x_{0} = 0\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Find the fixed point.", workingLatex: "\\alpha = -\\frac{\\alpha}{2} + 1\\ \\Rightarrow\\ \\frac{3\\alpha}{2} = 1\\ \\Rightarrow\\ \\alpha = \\frac{2}{3}", explanation: "" }, { stepNumber: 3, description: "Compute the slope: \\(g'(x) = -\\displaystyle\\frac{1}{2}\\).", workingLatex: "-1 < g'(\\alpha) = -\\tfrac{1}{2} < 0", explanation: "Negative slope between \\(-1\\) and \\(0\\) gives a converging cobweb." }, { stepNumber: 4, description: "Compute iterates explicitly.", workingLatex: "x_{1} = 1,\\ x_{2} = \\tfrac{1}{2},\\ x_{3} = \\tfrac{3}{4},\\ x_{4} = \\tfrac{5}{8},\\ x_{5} = \\tfrac{11}{16}", explanation: "Notice the iterates alternate above and below \\(\\alpha = \\tfrac{2}{3}\\)." }, { stepNumber: 5, description: "Construction: from \\(\\left(0, 0\\right)\\) up to the curve at \\(\\left(0, 1\\right)\\), across to \\(\\left(1, 1\\right)\\) on \\(y = x\\), then down to \\(\\left(1, 0.5\\right)\\), across to \\(\\left(0.5, 0.5\\right)\\), and so on — producing a rectangular spiral.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => -0.5 * x + 1, [0, 1.5], [0, 1.5], 0, 5) }, { stepNumber: 6, description: "Conclude: cobweb spiralling inward toward \\(\\alpha = \\tfrac{2}{3}\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Cobweb converging to \\(\\alpha = \\tfrac{2}{3}\\)." } },
  { id: "y2nm3-009", topicRef: "y2nm3", topicTitle: "Sketching Iteration 09", difficulty: "Foundation", questionText: "Sketch the cobweb diagram for \\(x_{n+1} = 2 - \\tfrac{1}{2} x_{n}\\) starting from \\(x_{0} = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb", "linear"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = 2 - \\displaystyle\\frac{x}{2}\\), starting from \\(x_{0} = 0\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Solve for the fixed point.", workingLatex: "\\alpha = 2 - \\frac{\\alpha}{2}\\ \\Rightarrow\\ \\frac{3\\alpha}{2} = 2\\ \\Rightarrow\\ \\alpha = \\frac{4}{3}", explanation: "" }, { stepNumber: 3, description: "Slope: \\(g'(x) = -\\displaystyle\\frac{1}{2}\\); since \\(-1 < -\\tfrac{1}{2} < 0\\) the diagram is a converging cobweb.", workingLatex: "", explanation: "" }, { stepNumber: 4, description: "Compute iterates.", workingLatex: "x_{1} = 2,\\ x_{2} = 1,\\ x_{3} = 1.5,\\ x_{4} = 1.25,\\ x_{5} = 1.375", explanation: "Iterates oscillate either side of \\(\\tfrac{4}{3} \\approx 1.333\\)." }, { stepNumber: 5, description: "Draw the cobweb: vertical from \\(\\left(0, 0\\right)\\) up to \\(\\left(0, 2\\right)\\), across to \\(\\left(2, 2\\right)\\), down to \\(\\left(2, 1\\right)\\), across to \\(\\left(1, 1\\right)\\), up to \\(\\left(1, 1.5\\right)\\), and continue — successive rectangles shrink toward \\(\\alpha\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 2 - 0.5 * x, [0, 2.5], [0, 2.5], 0, 5) }, { stepNumber: 6, description: "Conclude: spiral cobweb converging to \\(\\alpha = \\tfrac{4}{3}\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Cobweb converging to \\(\\alpha = \\tfrac{4}{3}\\)." } },
  { id: "y2nm3-010", topicRef: "y2nm3", topicTitle: "Sketching Iteration 10", difficulty: "Foundation", questionText: "Describe the behaviour of the iteration \\(x_{n+1} = 1.5 x_{n} - 0.5\\) starting from \\(x_{0} = 1.1\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["staircase", "divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = 1.5 x - 0.5\\) with \\(x_{0} = 1.1\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Locate the fixed point.", workingLatex: "\\alpha = 1.5\\alpha - 0.5\\ \\Rightarrow\\ 0.5\\alpha = 0.5\\ \\Rightarrow\\ \\alpha = 1", explanation: "" }, { stepNumber: 3, description: "Compute the slope.", workingLatex: "g'(x) = 1.5,\\quad g'(1) = 1.5 > 1", explanation: "\\(\\left|g'(\\alpha)\\right| > 1\\): the staircase moves away from \\(\\alpha\\)." }, { stepNumber: 4, description: "Iterate from \\(x_{0} = 1.1\\).", workingLatex: "x_{1} = 1.15,\\ x_{2} = 1.225,\\ x_{3} = 1.3375,\\ x_{4} \\approx 1.506", explanation: "Each iterate is \\(1.5\\) times the previous error: distance from \\(\\alpha\\) grows by \\(50\\%\\) per step." }, { stepNumber: 5, description: "On the sketch the staircase climbs upward and outward, away from \\(\\alpha = 1\\), because the curve is steeper than \\(y = x\\) at the intersection.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 1.5 * x - 0.5, [0.6, 2.2], [0.6, 2.2], 1.1, 3) }, { stepNumber: 6, description: "Conclude: the iteration diverges; \\(\\alpha = 1\\) is a repelling fixed point.", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase diverging from \\(\\alpha = 1\\)." } },
  { id: "y2nm3-011", topicRef: "y2nm3", topicTitle: "Sketching Iteration 11", difficulty: "Foundation", questionText: "Describe the behaviour of the iteration \\(x_{n+1} = -2 x_{n} + 3\\) starting from \\(x_{0} = 1.1\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["cobweb", "divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = -2 x + 3\\), \\(x_{0} = 1.1\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Find the fixed point.", workingLatex: "\\alpha = -2\\alpha + 3\\ \\Rightarrow\\ 3\\alpha = 3\\ \\Rightarrow\\ \\alpha = 1", explanation: "" }, { stepNumber: 3, description: "Compute the slope.", workingLatex: "g'(x) = -2,\\quad \\left|g'(\\alpha)\\right| = 2 > 1", explanation: "Negative slope and magnitude greater than 1: diverging cobweb." }, { stepNumber: 4, description: "Iterate.", workingLatex: "x_{1} = 0.8,\\ x_{2} = 1.4,\\ x_{3} = 0.2", explanation: "Each iterate doubles its distance from \\(\\alpha = 1\\), with alternating signs of the error." }, { stepNumber: 5, description: "Geometrically the rectangles of the cobweb grow outward and quickly leave the viewing window.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => -2 * x + 3, [0.1, 1.6], [0.1, 1.6], 1.1, 2) }, { stepNumber: 6, description: "Conclude: cobweb spiralling outward; iteration diverges.", workingLatex: "", explanation: "" } ], finalAnswer: "Cobweb spiralling outward from \\(\\alpha = 1\\); diverges." } },
  { id: "y2nm3-012", topicRef: "y2nm3", topicTitle: "Sketching Iteration 12", difficulty: "Foundation", questionText: "If \\(g'(\\alpha) = 0\\), describe the shape of the staircase diagram near the fixed point.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "Linearising \\(g\\) near \\(\\alpha\\) gives the error recurrence \\(e_{n+1} \\approx g'(\\alpha) e_{n}\\); with \\(g'(\\alpha) = 0\\) the linear term vanishes.", workingLatex: "e_{n+1} \\approx 0 \\cdot e_{n} + \\tfrac{1}{2} g''(\\alpha) e_{n}^{2}", explanation: "The next-order Taylor term takes over and the error contracts quadratically." }, { stepNumber: 2, description: "Geometrically the curve \\(y = g(x)\\) has a horizontal tangent at \\(\\left(\\alpha, \\alpha\\right)\\), so it crosses \\(y = x\\) at right-angles to the horizontal.", workingLatex: "", explanation: "The vertical move to the curve lands almost exactly at height \\(\\alpha\\) regardless of where we start nearby." }, { stepNumber: 3, description: "The staircase therefore consists of just one or two very steep steps before the iterates are practically on top of \\(\\alpha\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 0.5 * (x + 2 / x), [0.6, 2.6], [0.6, 2.6], 2.5, 3) }, { stepNumber: 4, description: "Such behaviour is characteristic of Newton–Raphson and Babylonian root-finding iterations.", workingLatex: "", explanation: "If \\(g'(\\alpha) = 0\\), the number of correct decimal places typically doubles at each step." } ], finalAnswer: "Very rapid (quadratic) convergence; the staircase has only one or two visible steps before iterates lock onto \\(\\alpha\\)." } },
  { id: "y2nm3-013", topicRef: "y2nm3", topicTitle: "Sketching Iteration 13", difficulty: "Foundation", questionText: "On a staircase diagram, from which element of the diagram do you read the value of \\(x_{1}\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the recurrence definition: each new iterate is the value of \\(g\\) at the current iterate.", workingLatex: "x_{1} = g(x_{0})", explanation: "" }, { stepNumber: 2, description: "On a diagram, draw a vertical line from \\(\\left(x_{0}, 0\\right)\\) up to the curve \\(y = g(x)\\). The \\(y\\)-coordinate of the meeting point is \\(g(x_{0}) = x_{1}\\).", workingLatex: "", explanation: "The 'height of the curve above \\(x_{0}\\)' is the next iterate." }, { stepNumber: 3, description: "To use \\(x_{1}\\) as the next input, draw a horizontal across to \\(y = x\\), reflecting the \\(y\\)-value back to the \\(x\\)-axis.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 0.5 * x + 0.5, [0, 1.5], [0, 1.5], 0, 4) }, { stepNumber: 4, description: "So \\(x_{1}\\) appears as both the \\(y\\)-coordinate of the curve at \\(x = x_{0}\\) and the \\(x\\)-coordinate at which the horizontal reaches \\(y = x\\).", workingLatex: "", explanation: "" } ], finalAnswer: "From the height of the curve \\(y = g(x)\\) directly above \\(x_{0}\\); equivalently, the \\(x\\)-coordinate where the horizontal step hits \\(y = x\\)." } },
  { id: "y2nm3-014", topicRef: "y2nm3", topicTitle: "Sketching Iteration 14", difficulty: "Foundation", questionText: "State the slope of the line \\(y = x\\) and explain why it always appears on a staircase diagram.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "The line \\(y = x\\) has slope \\(1\\) and passes through the origin.", workingLatex: "", explanation: "On this line every \\(y\\)-coordinate equals its \\(x\\)-coordinate." }, { stepNumber: 2, description: "After computing \\(x_{n+1} = g(x_{n})\\) we end up at the point \\(\\left(x_{n}, x_{n+1}\\right)\\) on the curve.", workingLatex: "", explanation: "The next vertical step needs the value \\(x_{n+1}\\) on the \\(x\\)-axis." }, { stepNumber: 3, description: "Moving horizontally to the line \\(y = x\\) takes us to \\(\\left(x_{n+1}, x_{n+1}\\right)\\) — converting the \\(y\\)-value into an \\(x\\)-value of the same magnitude.", workingLatex: "", explanation: "So \\(y = x\\) is the 'feedback channel' of the iteration.", diagram: cobwebDiagram((x) => 0.6 * x + 0.4, [0, 1.5], [0, 1.5], 0, 4) }, { stepNumber: 4, description: "Without \\(y = x\\) we would lose the mechanism that turns the output into the next input, and could not draw further steps.", workingLatex: "", explanation: "The fixed point — where \\(g(x) = x\\) — is also located using this line." } ], finalAnswer: "Slope \\(1\\). It is the geometric device that reflects each output \\(y = g(x_{n})\\) back to the \\(x\\)-axis as the next input \\(x_{n+1}\\)." } },
  { id: "y2nm3-015", topicRef: "y2nm3", topicTitle: "Sketching Iteration 15", difficulty: "Foundation", questionText: "A diagram shows \\(y = g(x)\\) crossing \\(y = x\\) at \\(\\alpha\\) with slope approximately 0.2. Classify the iteration's behaviour.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["classification"], workedSolution: { steps: [ { stepNumber: 1, description: "Read off the slope at \\(\\alpha\\): \\(g'(\\alpha) \\approx 0.2\\).", workingLatex: "0 < g'(\\alpha) = 0.2 < 1", explanation: "Positive and less than 1: the slope is in the staircase-convergence band." }, { stepNumber: 2, description: "Compare with the test: convergence needs \\(\\left|g'(\\alpha)\\right| < 1\\), satisfied here.", workingLatex: "\\left|g'(\\alpha)\\right| = 0.2 < 1", explanation: "" }, { stepNumber: 3, description: "Behaviour: a converging staircase — each step reduces the error by a factor of \\(0.2\\) (i.e.\\ \\(80\\%\\) reduction per iterate).", workingLatex: "", explanation: "Very fast convergence in practice.", diagram: cobwebDiagram((x) => 0.2 * x + 0.8, [0, 1.5], [0, 1.5], 0, 5) }, { stepNumber: 4, description: "Conclude: monotone convergence toward \\(\\alpha\\); no oscillation.", workingLatex: "", explanation: "" } ], finalAnswer: "Converging staircase (rapid; error decays by factor \\(0.2\\) per step)." } },
  { id: "y2nm3-016", topicRef: "y2nm3", topicTitle: "Sketching Iteration 16", difficulty: "Foundation", questionText: "A diagram shows \\(y = g(x)\\) crossing \\(y = x\\) at \\(\\alpha\\) with slope approximately \\(-0.3\\). Classify the iteration's behaviour.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["classification"], workedSolution: { steps: [ { stepNumber: 1, description: "Read off the slope: \\(g'(\\alpha) \\approx -0.3\\).", workingLatex: "-1 < g'(\\alpha) = -0.3 < 0", explanation: "Negative and of magnitude less than 1 — converging cobweb band." }, { stepNumber: 2, description: "Test convergence: \\(\\left|g'(\\alpha)\\right| = 0.3 < 1\\), so iterates approach \\(\\alpha\\).", workingLatex: "", explanation: "" }, { stepNumber: 3, description: "Because \\(g'(\\alpha) < 0\\), successive iterates lie on opposite sides of \\(\\alpha\\). The picture is a rectangular spiral.", workingLatex: "", explanation: "Error decays by factor \\(0.3\\) per step but alternates sign.", diagram: cobwebDiagram((x) => -0.3 * x + 1.3, [0, 1.8], [0, 1.8], 0.2, 6) }, { stepNumber: 4, description: "Conclude: cobweb converging to \\(\\alpha\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Converging cobweb (rapid; error reverses sign and shrinks by factor \\(0.3\\) per step)." } },
  { id: "y2nm3-017", topicRef: "y2nm3", topicTitle: "Sketching Iteration 17", difficulty: "Foundation", questionText: "A diagram shows \\(y = g(x)\\) crossing \\(y = x\\) at \\(\\alpha\\) with slope approximately 1.4. Classify the iteration's behaviour.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["classification", "divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Slope at \\(\\alpha\\) is positive and exceeds 1.", workingLatex: "g'(\\alpha) \\approx 1.4 > 1", explanation: "" }, { stepNumber: 2, description: "Convergence test fails: \\(\\left|g'(\\alpha)\\right| = 1.4 > 1\\).", workingLatex: "", explanation: "The iteration cannot settle at \\(\\alpha\\) — \\(\\alpha\\) is repelling." }, { stepNumber: 3, description: "Geometrically the curve is steeper than \\(y = x\\) at the crossing, so each vertical step overshoots more than the previous one in the same direction.", workingLatex: "", explanation: "The staircase climbs (or descends) away from \\(\\alpha\\).", diagram: cobwebDiagram((x) => 1.4 * x - 0.4, [0.5, 2], [0.5, 2], 1.1, 3) }, { stepNumber: 4, description: "Conclude: diverging staircase; iterates move monotonically away from \\(\\alpha\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Diverging staircase — iterates move away from \\(\\alpha\\)." } },
  { id: "y2nm3-018", topicRef: "y2nm3", topicTitle: "Sketching Iteration 18", difficulty: "Foundation", questionText: "A diagram shows \\(y = g(x)\\) crossing \\(y = x\\) at \\(\\alpha\\) with slope approximately \\(-1.5\\). Classify the iteration's behaviour.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["classification", "divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Read the slope: \\(g'(\\alpha) \\approx -1.5\\).", workingLatex: "g'(\\alpha) < -1", explanation: "Negative slope with magnitude exceeding 1." }, { stepNumber: 2, description: "Convergence test: \\(\\left|g'(\\alpha)\\right| = 1.5 > 1\\), so the iteration cannot converge.", workingLatex: "", explanation: "" }, { stepNumber: 3, description: "Sign of \\(g'\\) is negative, so iterates alternate sides of \\(\\alpha\\) (cobweb pattern), and magnitude > 1 forces them outward (diverging).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => -1.5 * x + 2.5, [0.3, 1.7], [0.3, 1.7], 1.1, 2) }, { stepNumber: 4, description: "Conclude: diverging cobweb — successive rectangles get larger and the iterates spiral outward.", workingLatex: "", explanation: "" } ], finalAnswer: "Diverging cobweb; iterates spiral outward away from \\(\\alpha\\)." } },
  { id: "y2nm3-019", topicRef: "y2nm3", topicTitle: "Sketching Iteration 19", difficulty: "Standard", questionText: "Sketch the staircase diagram for \\(x_{n+1} = \\sqrt{x_{n} + 2}\\) starting from \\(x_{0} = 0\\). State the fixed point.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration: \\(g(x) = \\sqrt{x + 2}\\), \\(x_{0} = 0\\).", workingLatex: "", explanation: "Domain requires \\(x \\geq -2\\); we operate in \\(x \\geq 0\\)." }, { stepNumber: 2, description: "Solve \\(\\alpha = g(\\alpha)\\). Square both sides (valid since \\(\\alpha \\geq 0\\)).", workingLatex: "\\alpha^{2} = \\alpha + 2\\ \\Rightarrow\\ \\alpha^{2} - \\alpha - 2 = 0\\ \\Rightarrow\\ (\\alpha - 2)(\\alpha + 1) = 0", explanation: "Positive root: \\(\\alpha = 2\\)." }, { stepNumber: 3, description: "Differentiate \\(g\\) and evaluate at \\(\\alpha\\).", workingLatex: "g'(x) = \\frac{1}{2\\sqrt{x + 2}},\\quad g'(2) = \\frac{1}{2\\sqrt{4}} = \\frac{1}{4}", explanation: "\\(0 < g'(2) < 1\\): converging staircase." }, { stepNumber: 4, description: "Iterates from \\(x_{0} = 0\\).", workingLatex: "x_{1} = \\sqrt{2} \\approx 1.414,\\ x_{2} \\approx 1.848,\\ x_{3} \\approx 1.962,\\ x_{4} \\approx 1.990", explanation: "Iterates climb monotonically toward 2." }, { stepNumber: 5, description: "The staircase rises from \\(\\left(0, 0\\right)\\), each step shorter than the last as the curve flattens.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => Math.sqrt(x + 2), [0, 2.5], [0, 2.5], 0, 5) }, { stepNumber: 6, description: "Conclude: staircase converges monotonically to \\(\\alpha = 2\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase converging to \\(\\alpha = 2\\)." } },
  { id: "y2nm3-020", topicRef: "y2nm3", topicTitle: "Sketching Iteration 20", difficulty: "Standard", questionText: "Sketch the staircase diagram for \\(x_{n+1} = \\sqrt[3]{x_{n} + 1}\\) starting from \\(x_{0} = 1\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = (x + 1)^{1/3}\\), \\(x_{0} = 1\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Solve \\(\\alpha = g(\\alpha)\\) by cubing both sides.", workingLatex: "\\alpha^{3} = \\alpha + 1\\ \\Rightarrow\\ \\alpha^{3} - \\alpha - 1 = 0", explanation: "This cubic has one real root \\(\\alpha \\approx 1.3247\\)." }, { stepNumber: 3, description: "Differentiate \\(g\\).", workingLatex: "g'(x) = \\frac{1}{3}(x + 1)^{-2/3},\\quad g'(\\alpha) = \\frac{1}{3 \\alpha^{2}} \\approx \\frac{1}{3 (1.755)} \\approx 0.190", explanation: "\\(0 < g'(\\alpha) < 1\\) so converging staircase." }, { stepNumber: 4, description: "Iterates from \\(x_{0} = 1\\).", workingLatex: "x_{1} = \\sqrt[3]{2} \\approx 1.2599,\\ x_{2} \\approx 1.3123,\\ x_{3} \\approx 1.3224,\\ x_{4} \\approx 1.3243", explanation: "Rapid convergence toward 1.3247." }, { stepNumber: 5, description: "Sketch: vertical to curve at height \\(\\sqrt[3]{2}\\), across to \\(y = x\\), up again, and so on; the steps shrink quickly.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => Math.cbrt(x + 1), [0.5, 2], [0.5, 2], 1, 5) }, { stepNumber: 6, description: "Conclude: monotone staircase converging to \\(\\alpha \\approx 1.3247\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase converging to \\(\\alpha \\approx 1.3247\\)." } },
  { id: "y2nm3-021", topicRef: "y2nm3", topicTitle: "Sketching Iteration 21", difficulty: "Standard", questionText: "Sketch the cobweb diagram for \\(x_{n+1} = \\cos x_{n}\\) (radians) starting from \\(x_{0} = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration: \\(g(x) = \\cos x\\) (radians), \\(x_{0} = 0\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Fixed-point equation \\(\\alpha = \\cos \\alpha\\) cannot be solved exactly; numerically \\(\\alpha \\approx 0.7391\\).", workingLatex: "", explanation: "This is the famous Dottie number." }, { stepNumber: 3, description: "Differentiate: \\(g'(x) = -\\sin x\\). At the fixed point.", workingLatex: "g'(\\alpha) = -\\sin(0.7391) \\approx -0.6736", explanation: "Negative magnitude less than 1: converging cobweb." }, { stepNumber: 4, description: "Iterates from \\(x_{0} = 0\\).", workingLatex: "x_{1} = 1.0000,\\ x_{2} \\approx 0.5403,\\ x_{3} \\approx 0.8576,\\ x_{4} \\approx 0.6543,\\ x_{5} \\approx 0.7935,\\ x_{6} \\approx 0.7014", explanation: "Iterates alternate above and below \\(\\alpha\\) and slowly close in." }, { stepNumber: 5, description: "Sketch shows a rectangular spiral homing in on \\(\\alpha\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => Math.cos(x), [0, 1.3], [0, 1.3], 0, 6) }, { stepNumber: 6, description: "Conclude: cobweb converging slowly to \\(\\alpha \\approx 0.7391\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Cobweb converging to \\(\\alpha \\approx 0.7391\\)." } },
  { id: "y2nm3-022", topicRef: "y2nm3", topicTitle: "Sketching Iteration 22", difficulty: "Standard", questionText: "Sketch the cobweb diagram for \\(x_{n+1} = e^{-x_{n}}\\) starting from \\(x_{0} = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb", "exponential"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = e^{-x}\\), \\(x_{0} = 0\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Fixed-point equation \\(\\alpha = e^{-\\alpha}\\) has a unique real solution \\(\\alpha \\approx 0.5671\\) (the omega constant).", workingLatex: "", explanation: "" }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = -e^{-x},\\quad g'(\\alpha) = -e^{-\\alpha} = -\\alpha \\approx -0.5671", explanation: "Using \\(e^{-\\alpha} = \\alpha\\)." }, { stepNumber: 4, description: "Magnitude \\(\\approx 0.567 < 1\\): converging cobweb.", workingLatex: "", explanation: "" }, { stepNumber: 5, description: "Iterates from \\(x_{0} = 0\\).", workingLatex: "x_{1} = 1.0000,\\ x_{2} \\approx 0.3679,\\ x_{3} \\approx 0.6922,\\ x_{4} \\approx 0.5005,\\ x_{5} \\approx 0.6062,\\ x_{6} \\approx 0.5454", explanation: "Successive iterates alternate either side of \\(\\alpha\\)." }, { stepNumber: 6, description: "Construct the cobweb: rectangular spiral inward toward \\(\\alpha\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => Math.exp(-x), [0, 1.2], [0, 1.2], 0, 6) }, { stepNumber: 7, description: "Conclude: cobweb converging to \\(\\alpha \\approx 0.5671\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Cobweb converging to \\(\\alpha \\approx 0.5671\\)." } },
  { id: "y2nm3-023", topicRef: "y2nm3", topicTitle: "Sketching Iteration 23", difficulty: "Standard", questionText: "Sketch the staircase diagram for \\(x_{n+1} = \\ln(x_{n} + 2)\\) starting from \\(x_{0} = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = \\ln(x + 2)\\), \\(x_{0} = 0\\).", workingLatex: "", explanation: "Domain: \\(x > -2\\)." }, { stepNumber: 2, description: "Fixed-point equation \\(\\alpha = \\ln(\\alpha + 2)\\); numerically \\(\\alpha \\approx 1.1462\\).", workingLatex: "", explanation: "Solve by Newton or iteration since no closed form exists." }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = \\frac{1}{x + 2},\\quad g'(\\alpha) = \\frac{1}{\\alpha + 2} \\approx \\frac{1}{3.146} \\approx 0.318", explanation: "\\(0 < g'(\\alpha) < 1\\): converging staircase." }, { stepNumber: 4, description: "Iterates from \\(0\\).", workingLatex: "x_{1} = \\ln 2 \\approx 0.693,\\ x_{2} \\approx 0.991,\\ x_{3} \\approx 1.096,\\ x_{4} \\approx 1.130,\\ x_{5} \\approx 1.141", explanation: "Monotone increase toward \\(1.146\\)." }, { stepNumber: 5, description: "Staircase: vertical to curve, horizontal to \\(y = x\\), steps shorten as they approach \\(\\alpha\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => Math.log(x + 2), [0, 2], [0, 2], 0, 5) }, { stepNumber: 6, description: "Conclude: monotone staircase converging to \\(\\alpha \\approx 1.146\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase converging to \\(\\alpha \\approx 1.146\\)." } },
  { id: "y2nm3-024", topicRef: "y2nm3", topicTitle: "Sketching Iteration 24", difficulty: "Standard", questionText: "Sketch the cobweb diagram for \\(x_{n+1} = 1 + \\tfrac{1}{x_{n}}\\) starting from \\(x_{0} = 1\\). State the fixed point.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = 1 + \\displaystyle\\frac{1}{x}\\), \\(x_{0} = 1\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Find the fixed point.", workingLatex: "\\alpha = 1 + \\frac{1}{\\alpha}\\ \\Rightarrow\\ \\alpha^{2} - \\alpha - 1 = 0\\ \\Rightarrow\\ \\alpha = \\frac{1 + \\sqrt{5}}{2}", explanation: "The golden ratio \\(\\varphi \\approx 1.6180\\)." }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = -\\frac{1}{x^{2}},\\quad g'(\\varphi) = -\\frac{1}{\\varphi^{2}} = -(2 - \\varphi) \\approx -0.382", explanation: "Used \\(\\varphi^{2} = \\varphi + 1\\). Magnitude \\(< 1\\): converging cobweb." }, { stepNumber: 4, description: "Iterates from \\(x_{0} = 1\\).", workingLatex: "x_{1} = 2,\\ x_{2} = 1.5,\\ x_{3} \\approx 1.6667,\\ x_{4} = 1.6,\\ x_{5} = 1.625,\\ x_{6} \\approx 1.6154", explanation: "These are ratios of consecutive Fibonacci numbers; they alternate around \\(\\varphi\\)." }, { stepNumber: 5, description: "Sketch the cobweb: rectangles spiral inward around \\(\\varphi\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 1 + 1 / x, [0.7, 2.2], [0.7, 2.2], 1, 6) }, { stepNumber: 6, description: "Conclude: cobweb converges to \\(\\varphi = \\displaystyle\\frac{1 + \\sqrt{5}}{2}\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Cobweb converging to \\(\\varphi = \\displaystyle\\frac{1 + \\sqrt{5}}{2} \\approx 1.6180\\)." } },
  { id: "y2nm3-025", topicRef: "y2nm3", topicTitle: "Sketching Iteration 25", difficulty: "Standard", questionText: "Sketch the staircase diagram for the Babylonian iteration \\(x_{n+1} = \\tfrac{1}{2}(x_{n} + \\tfrac{5}{x_{n}})\\) starting from \\(x_{0} = 1\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase", "babylonian"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration: \\(g(x) = \\displaystyle\\frac{1}{2}\\!\\left(x + \\frac{5}{x}\\right)\\), \\(x_{0} = 1\\).", workingLatex: "", explanation: "This is the Babylonian method for \\(\\sqrt{5}\\)." }, { stepNumber: 2, description: "Find fixed points.", workingLatex: "\\alpha = \\frac{1}{2}\\!\\left(\\alpha + \\frac{5}{\\alpha}\\right)\\ \\Rightarrow\\ \\alpha^{2} = 5\\ \\Rightarrow\\ \\alpha = \\sqrt{5} \\approx 2.236", explanation: "(Taking the positive root since \\(x_{0} > 0\\).)" }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = \\frac{1}{2}\\!\\left(1 - \\frac{5}{x^{2}}\\right),\\quad g'(\\sqrt{5}) = \\frac{1}{2}(1 - 1) = 0", explanation: "Zero slope at the fixed point gives quadratic convergence." }, { stepNumber: 4, description: "Iterates from \\(x_{0} = 1\\).", workingLatex: "x_{1} = 3,\\ x_{2} \\approx 2.3333,\\ x_{3} \\approx 2.2381,\\ x_{4} \\approx 2.2361", explanation: "After only three iterates we have 4 d.p. accuracy." }, { stepNumber: 5, description: "Sketch: a tall first step from \\(\\left(1, 0\\right)\\) up to \\(\\left(1, 3\\right)\\), then iterates lock onto \\(\\alpha\\) almost immediately.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 0.5 * (x + 5 / x), [0.8, 3.2], [0.8, 3.2], 1, 3) }, { stepNumber: 6, description: "Conclude: staircase converges quadratically (very fast) to \\(\\sqrt{5}\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase converging quadratically to \\(\\sqrt{5} \\approx 2.236\\)." } },
  { id: "y2nm3-026", topicRef: "y2nm3", topicTitle: "Sketching Iteration 26", difficulty: "Standard", questionText: "Sketch the cobweb diagram for \\(x_{n+1} = \\tfrac{1}{2}\\cos x_{n}\\) starting from \\(x_{0} = 0\\). Work in radians.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = \\displaystyle\\frac{1}{2}\\cos x\\), \\(x_{0} = 0\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Fixed-point equation \\(\\alpha = \\tfrac{1}{2}\\cos \\alpha\\); numerically \\(\\alpha \\approx 0.4502\\).", workingLatex: "", explanation: "" }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = -\\frac{1}{2}\\sin x,\\quad g'(\\alpha) \\approx -0.2176", explanation: "Small magnitude — fast convergence." }, { stepNumber: 4, description: "Iterates from \\(0\\).", workingLatex: "x_{1} = 0.5,\\ x_{2} \\approx 0.4388,\\ x_{3} \\approx 0.4526,\\ x_{4} \\approx 0.4496,\\ x_{5} \\approx 0.4503", explanation: "Iterates alternate either side of \\(\\alpha\\) and close in within four steps." }, { stepNumber: 5, description: "Construct the cobweb: small rectangles tightly wrapping around \\(\\alpha\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 0.5 * Math.cos(x), [0, 0.7], [0, 0.7], 0, 5) }, { stepNumber: 6, description: "Conclude: cobweb converging rapidly to \\(\\alpha \\approx 0.4502\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Cobweb converging to \\(\\alpha \\approx 0.4502\\)." } },
  { id: "y2nm3-027", topicRef: "y2nm3", topicTitle: "Sketching Iteration 27", difficulty: "Standard", questionText: "Sketch the staircase diagram for \\(x_{n+1} = \\sqrt{3 x_{n} - 2}\\) starting from \\(x_{0} = 1\\) and show convergence to \\(\\alpha = 2\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = \\sqrt{3x - 2}\\), \\(x_{0} = 1\\). Domain: \\(x \\geq \\tfrac{2}{3}\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Square both sides of \\(\\alpha = g(\\alpha)\\).", workingLatex: "\\alpha^{2} = 3\\alpha - 2\\ \\Rightarrow\\ \\alpha^{2} - 3\\alpha + 2 = 0\\ \\Rightarrow\\ \\alpha = 1\\ \\text{or}\\ \\alpha = 2", explanation: "Two fixed points." }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = \\frac{3}{2\\sqrt{3x - 2}},\\quad g'(1) = \\frac{3}{2},\\ g'(2) = \\frac{3}{4}", explanation: "\\(\\alpha = 1\\) is repelling; \\(\\alpha = 2\\) is attracting." }, { stepNumber: 4, description: "Note that starting exactly at \\(x_{0} = 1\\) leaves the iterate stuck at \\(1\\); but a tiny perturbation pushes us toward \\(2\\). For instance from \\(x_{0} = 1.01\\):", workingLatex: "x_{1} \\approx 1.0149,\\ x_{2} \\approx 1.0223,\\ \\ldots \\to 2", explanation: "In an exam sketch we set the starting point a small bit above 1 to make the staircase visible." }, { stepNumber: 5, description: "Sketch: a slow staircase climbing from just above \\(1\\) toward \\(2\\); each step shorter as the curve flattens near \\(\\alpha = 2\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => Math.sqrt(3 * x - 2), [0.8, 2.5], [0.8, 2.5], 1.05, 6) }, { stepNumber: 6, description: "Conclude: staircase converges to the attracting fixed point \\(\\alpha = 2\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase converging to \\(\\alpha = 2\\) (the attracting root)." } },
  { id: "y2nm3-028", topicRef: "y2nm3", topicTitle: "Sketching Iteration 28", difficulty: "Standard", questionText: "Sketch the staircase diagram for \\(x_{n+1} = 3 - \\tfrac{2}{x_{n}}\\) starting from \\(x_{0} = 2\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = 3 - \\displaystyle\\frac{2}{x}\\), \\(x_{0} = 2\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Find fixed points. Multiply by \\(\\alpha\\):", workingLatex: "\\alpha \\cdot \\alpha = 3\\alpha - 2\\ \\Rightarrow\\ \\alpha^{2} - 3\\alpha + 2 = 0\\ \\Rightarrow\\ \\alpha = 1\\ \\text{or}\\ \\alpha = 2", explanation: "" }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = \\frac{2}{x^{2}},\\quad g'(1) = 2,\\ g'(2) = \\frac{1}{2}", explanation: "\\(\\alpha = 1\\) repelling; \\(\\alpha = 2\\) attracting." }, { stepNumber: 4, description: "Starting at \\(x_{0} = 2\\) the iteration is already at the attracting fixed point.", workingLatex: "x_{1} = 3 - 1 = 2,\\ x_{2} = 2,\\ \\ldots", explanation: "Every iterate stays at 2." }, { stepNumber: 5, description: "On the diagram the trajectory is just the single point \\(\\left(2, 2\\right)\\); for a visible staircase one would start near (but not at) 2.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 3 - 2 / x, [1, 3], [1, 3], 2.4, 4) }, { stepNumber: 6, description: "Conclude: \\(\\alpha = 2\\) is attractive with slope \\(0.5\\); the iteration stays at 2 if started there.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(\\alpha = 2\\) is attractive (slope \\(\\tfrac{1}{2}\\)); the iteration stays at \\(\\alpha = 2\\)." } },
  { id: "y2nm3-029", topicRef: "y2nm3", topicTitle: "Sketching Iteration 29", difficulty: "Standard", questionText: "For the iteration in Q28, show that starting from \\(x_{0} = 1.2\\) iteration diverges away from \\(\\alpha = 1\\) and lands on the other fixed point.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase", "stability"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall \\(g(x) = 3 - \\displaystyle\\frac{2}{x}\\) with fixed points \\(\\alpha_{1} = 1\\) (repelling, \\(g'(1) = 2\\)) and \\(\\alpha_{2} = 2\\) (attracting, \\(g'(2) = \\tfrac{1}{2}\\)).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Compute iterates from \\(x_{0} = 1.2\\).", workingLatex: "x_{1} = 3 - \\frac{2}{1.2} = \\frac{4}{3} \\approx 1.333", explanation: "" }, { stepNumber: 3, description: "Continue.", workingLatex: "x_{2} = \\frac{3}{2},\\ x_{3} = \\frac{5}{3},\\ x_{4} = 1.8,\\ x_{5} \\approx 1.889,\\ x_{6} \\approx 1.941", explanation: "Iterates move steadily away from \\(\\alpha_{1} = 1\\) and toward \\(\\alpha_{2} = 2\\)." }, { stepNumber: 4, description: "Slope test: at \\(x_{0} = 1.2\\) the curve is steeper than \\(y = x\\) (since \\(g'(1.2) = \\tfrac{2}{1.44} \\approx 1.39 > 1\\)), so locally the staircase moves outward — away from 1.", workingLatex: "", explanation: "But as \\(x\\) grows past \\(\\sqrt{2} \\approx 1.41\\) the slope drops below 1 and the staircase begins to settle on \\(\\alpha_{2}\\)." }, { stepNumber: 5, description: "Sketch shows a staircase rising from \\(1.2\\) through the unstable region and locking onto \\(2\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 3 - 2 / x, [0.8, 2.5], [0.8, 2.5], 1.2, 6) }, { stepNumber: 6, description: "Conclude: the iterates abandon the unstable \\(\\alpha = 1\\) and settle at the stable \\(\\alpha = 2\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Iterates leave \\(\\alpha = 1\\) and settle at \\(\\alpha = 2\\)." } },
  { id: "y2nm3-030", topicRef: "y2nm3", topicTitle: "Sketching Iteration 30", difficulty: "Standard", questionText: "Sketch the staircase diagram for \\(x_{n+1} = \\sqrt[3]{2 x_{n} + 5}\\) starting from \\(x_{0} = 2\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = (2x + 5)^{1/3}\\), \\(x_{0} = 2\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Cube the fixed-point equation.", workingLatex: "\\alpha^{3} = 2\\alpha + 5\\ \\Rightarrow\\ \\alpha^{3} - 2\\alpha - 5 = 0", explanation: "Numerically \\(\\alpha \\approx 2.0946\\) (Wallis's cubic)." }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = \\frac{2}{3}(2x + 5)^{-2/3},\\quad g'(\\alpha) = \\frac{2}{3 \\alpha^{2}} \\approx \\frac{2}{3 (4.388)} \\approx 0.152", explanation: "\\(0 < g'(\\alpha) < 1\\): converging staircase." }, { stepNumber: 4, description: "Iterates from \\(2\\).", workingLatex: "x_{1} \\approx 2.0801,\\ x_{2} \\approx 2.0924,\\ x_{3} \\approx 2.0942,\\ x_{4} \\approx 2.0945", explanation: "Convergence to 4 d.p. in three iterates." }, { stepNumber: 5, description: "Sketch: tiny staircase climbing imperceptibly from \\(2\\) to \\(\\alpha\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => Math.cbrt(2 * x + 5), [1.5, 2.5], [1.5, 2.5], 2, 4) }, { stepNumber: 6, description: "Conclude: monotone staircase converging rapidly to \\(\\alpha \\approx 2.0946\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase converging to \\(\\alpha \\approx 2.0946\\)." } },
  { id: "y2nm3-031", topicRef: "y2nm3", topicTitle: "Sketching Iteration 31", difficulty: "Standard", questionText: "Sketch the diagram for \\(x_{n+1} = -x_{n}^{3} + 3\\) starting from \\(x_{0} = 1.2\\). Does the iteration converge near the fixed point \\(\\alpha \\approx 1.2134\\)?", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb", "divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = -x^{3} + 3\\), \\(x_{0} = 1.2\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Fixed-point equation \\(\\alpha + \\alpha^{3} = 3\\); numerically \\(\\alpha \\approx 1.2134\\).", workingLatex: "", explanation: "" }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = -3 x^{2},\\quad g'(\\alpha) \\approx -3 (1.2134)^{2} \\approx -4.417", explanation: "\\(\\left|g'(\\alpha)\\right| \\approx 4.4 \\gg 1\\): cobweb diverges spectacularly." }, { stepNumber: 4, description: "Iterates from \\(x_{0} = 1.2\\).", workingLatex: "x_{1} = 1.272,\\ x_{2} \\approx 0.942,\\ x_{3} \\approx 2.164,\\ \\ldots", explanation: "Iterates already wildly off the fixed point after only a few steps." }, { stepNumber: 5, description: "Sketch: the cobweb rectangles balloon outward; the trajectory leaves any reasonable window.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => -x * x * x + 3, [0, 2.5], [0, 2.5], 1.2, 2) }, { stepNumber: 6, description: "Conclude: no — the iteration does not converge to \\(\\alpha\\).", workingLatex: "", explanation: "" } ], finalAnswer: "No — cobweb diverges." } },
  { id: "y2nm3-032", topicRef: "y2nm3", topicTitle: "Sketching Iteration 32", difficulty: "Standard", questionText: "Sketch the cobweb diagram for \\(x_{n+1} = \\tfrac{1}{\\sqrt{x_{n} + 1}}\\) starting from \\(x_{0} = 1\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = (x + 1)^{-1/2}\\), \\(x_{0} = 1\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Square \\(\\alpha = g(\\alpha)\\) to get \\(\\alpha^{2}(\\alpha + 1) = 1\\), i.e.\\ \\(\\alpha^{3} + \\alpha^{2} - 1 = 0\\); numerically \\(\\alpha \\approx 0.7549\\).", workingLatex: "", explanation: "" }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = -\\frac{1}{2}(x + 1)^{-3/2},\\quad g'(\\alpha) \\approx -\\frac{1}{2}(1.7549)^{-3/2} \\approx -0.2151", explanation: "Magnitude \\(< 1\\), sign \\(-\\): converging cobweb." }, { stepNumber: 4, description: "Iterates from \\(1\\).", workingLatex: "x_{1} = \\frac{1}{\\sqrt{2}} \\approx 0.7071,\\ x_{2} \\approx 0.7654,\\ x_{3} \\approx 0.7526,\\ x_{4} \\approx 0.7554,\\ x_{5} \\approx 0.7548", explanation: "Iterates alternate around \\(\\alpha\\) and close in within five steps." }, { stepNumber: 5, description: "Sketch: small rectangular spiral homing in on \\(\\alpha\\).", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 1 / Math.sqrt(x + 1), [0.3, 1.1], [0.3, 1.1], 1, 5) }, { stepNumber: 6, description: "Conclude: cobweb converges rapidly to \\(\\alpha \\approx 0.7549\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Cobweb converging to \\(\\alpha \\approx 0.7549\\)." } },
  { id: "y2nm3-033", topicRef: "y2nm3", topicTitle: "Sketching Iteration 33", difficulty: "Standard", questionText: "The iteration \\(x_{n+1} = 1 - x_{n}\\) starts from \\(x_{0} = 0.2\\). Sketch the diagram and describe the behaviour.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["cobweb", "periodic"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = 1 - x\\), \\(x_{0} = 0.2\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Find the fixed point.", workingLatex: "\\alpha = 1 - \\alpha\\ \\Rightarrow\\ \\alpha = \\frac{1}{2}", explanation: "" }, { stepNumber: 3, description: "Slope: \\(g'(x) = -1\\). Borderline case \\(\\left|g'(\\alpha)\\right| = 1\\) — linear analysis cannot decide convergence.", workingLatex: "", explanation: "" }, { stepNumber: 4, description: "Iterate explicitly.", workingLatex: "x_{0} = 0.2,\\ x_{1} = 0.8,\\ x_{2} = 0.2,\\ x_{3} = 0.8,\\ \\ldots", explanation: "The sequence flips between two values forever — a period-2 cycle." }, { stepNumber: 5, description: "On the diagram the trajectory traces a perfect square: \\(\\left(0.2, 0\\right) \\to \\left(0.2, 0.8\\right) \\to \\left(0.8, 0.8\\right) \\to \\left(0.8, 0.2\\right) \\to \\left(0.2, 0.2\\right) \\to \\ldots\\) and never collapses.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => 1 - x, [0, 1], [0, 1], 0.2, 4) }, { stepNumber: 6, description: "Conclude: square cobweb; period-2 oscillation, no convergence.", workingLatex: "", explanation: "" } ], finalAnswer: "Square cobweb; the sequence cycles between \\(0.2\\) and \\(0.8\\) and does not converge." } },
  { id: "y2nm3-034", topicRef: "y2nm3", topicTitle: "Sketching Iteration 34", difficulty: "Standard", questionText: "Describe the behaviour of \\(x_{n+1} = x_{n}^{2}\\) from \\(x_{0} = 0.5\\). Include the fixed points.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(g(x) = x^{2}\\), \\(x_{0} = 0.5\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Solve fixed-point equation.", workingLatex: "\\alpha^{2} = \\alpha\\ \\Rightarrow\\ \\alpha(\\alpha - 1) = 0\\ \\Rightarrow\\ \\alpha = 0\\ \\text{or}\\ \\alpha = 1", explanation: "" }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = 2x,\\quad g'(0) = 0,\\ g'(1) = 2", explanation: "\\(\\alpha = 0\\) is strongly attracting; \\(\\alpha = 1\\) is repelling." }, { stepNumber: 4, description: "Iterates from \\(0.5\\).", workingLatex: "x_{1} = 0.25,\\ x_{2} = 0.0625,\\ x_{3} \\approx 0.0039,\\ x_{4} \\approx 1.5 \\times 10^{-5}", explanation: "Each iterate is the square of the previous; convergence to 0 is super-fast (quadratic)." }, { stepNumber: 5, description: "The staircase descends from \\(0.5\\) toward the attracting fixed point at \\(0\\); steps shrink dramatically.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => x * x, [0, 1.1], [0, 1.1], 0.5, 5) }, { stepNumber: 6, description: "Conclude: monotone staircase converging quadratically to \\(\\alpha = 0\\); the other fixed point \\(\\alpha = 1\\) is unstable.", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase converging (quadratically) to \\(\\alpha = 0\\); \\(\\alpha = 1\\) is repelling." } },
  { id: "y2nm3-035", topicRef: "y2nm3", topicTitle: "Sketching Iteration 35", difficulty: "Standard", questionText: "Describe the behaviour of \\(x_{n+1} = x_{n}^{2}\\) starting from \\(x_{0} = 1.1\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["staircase", "divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Same iteration as Q34: \\(g(x) = x^{2}\\), with fixed points \\(0\\) (attracting) and \\(1\\) (repelling, slope \\(2\\)).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Starting just above the repelling point \\(\\alpha = 1\\) gives a diverging staircase.", workingLatex: "g'(1) = 2 > 1", explanation: "" }, { stepNumber: 3, description: "Iterates from \\(1.1\\).", workingLatex: "x_{1} = 1.21,\\ x_{2} = 1.4641,\\ x_{3} \\approx 2.1436,\\ x_{4} \\approx 4.595", explanation: "Each iterate is the square of the previous; values grow without bound." }, { stepNumber: 4, description: "On the sketch, the curve \\(y = x^{2}\\) is well above \\(y = x\\) for \\(x > 1\\), so each vertical step ascends, then the horizontal step moves further right.", workingLatex: "", explanation: "", diagram: cobwebDiagram((x) => x * x, [0.9, 2.5], [0.9, 2.5], 1.1, 2) }, { stepNumber: 5, description: "Conclude: staircase diverges to \\(+\\infty\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Staircase diverging to \\(+\\infty\\)." } },
  { id: "y2nm3-036", topicRef: "y2nm3", topicTitle: "Sketching Iteration 36", difficulty: "Standard", questionText: "Identify the two fixed points of \\(x_{n+1} = x_{n}^{2} - 0.5\\) and state which is attracting.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["fixed point", "stability"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = x^{2} - \\frac{1}{2}", explanation: "A fixed point \\(\\alpha\\) satisfies \\(g(\\alpha) = \\alpha\\), i.e.\\ the curve \\(y = g(x)\\) crosses \\(y = x\\)." }, { stepNumber: 2, description: "Set up the fixed-point equation \\(\\alpha = \\alpha^{2} - \\displaystyle\\frac{1}{2}\\).", workingLatex: "\\alpha^{2} - \\alpha - \\frac{1}{2} = 0", explanation: "Bring everything to one side and solve as a quadratic in \\(\\alpha\\)." }, { stepNumber: 3, description: "Apply the quadratic formula with \\(a = 1,\\ b = -1,\\ c = -\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\alpha = \\frac{1 \\pm \\sqrt{1 + 2}}{2} = \\frac{1 \\pm \\sqrt{3}}{2}", explanation: "So \\(\\alpha_{1} = \\displaystyle\\frac{1 + \\sqrt{3}}{2} \\approx 1.3660\\) and \\(\\alpha_{2} = \\displaystyle\\frac{1 - \\sqrt{3}}{2} \\approx -0.3660\\)." }, { stepNumber: 4, description: "Differentiate \\(g\\) and evaluate at each fixed point.", workingLatex: "g'(x) = 2x", explanation: "\\(g'(\\alpha_{1}) = 1 + \\sqrt{3} \\approx 2.732\\) and \\(g'(\\alpha_{2}) = 1 - \\sqrt{3} \\approx -0.732\\)." }, { stepNumber: 5, description: "Apply the convergence criterion \\(|g'(\\alpha)| < 1\\).", workingLatex: "|g'(\\alpha_{1})| \\approx 2.732 > 1, \\qquad |g'(\\alpha_{2})| \\approx 0.732 < 1", explanation: "Hence \\(\\alpha_{1}\\) is repelling (small errors grow) and \\(\\alpha_{2}\\) is attracting. Because \\(g'(\\alpha_{2}) < 0\\), iterates near \\(\\alpha_{2}\\) form a cobweb." }, { stepNumber: 6, description: "Sketch \\(y = x^{2} - 0.5\\) with \\(y = x\\) and trace a few iterates from \\(x_{0} = 0\\).", workingLatex: "x_{1} = -0.5,\\ x_{2} = -0.25,\\ x_{3} \\approx -0.4375,\\ x_{4} \\approx -0.309", explanation: "Iterates oscillate either side of \\(\\alpha_{2}\\) and close in on it.", diagram: cobwebDiagram((x) => x * x - 0.5, [-1, 1.6], [-1, 1.6], 0, 4) } ], finalAnswer: "\\(\\alpha_{2} \\approx -0.366\\) is attracting; \\(\\alpha_{1}\\) is repelling." } },
  { id: "y2nm3-037", topicRef: "y2nm3", topicTitle: "Sketching Iteration 37", difficulty: "Standard", questionText: "Sketch the diagram for the iteration in Q36 starting from \\(x_{0} = -0.2\\) and confirm convergence to the stable fixed point.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the iteration and its attracting fixed point.", workingLatex: "x_{n+1} = x_{n}^{2} - \\frac{1}{2}, \\qquad \\alpha_{2} = \\frac{1 - \\sqrt{3}}{2} \\approx -0.3660", explanation: "From Q36, \\(g'(\\alpha_{2}) = 1 - \\sqrt{3} \\approx -0.732\\); since \\(-1 < g'(\\alpha_{2}) < 0\\), iterates form a cobweb that converges." }, { stepNumber: 2, description: "Compute the first few iterates from \\(x_{0} = -0.2\\).", workingLatex: "x_{1} = (-0.2)^{2} - 0.5 = -0.4600", explanation: "\\(x_{2} = (-0.46)^{2} - 0.5 = -0.2884,\\ x_{3} \\approx -0.4168,\\ x_{4} \\approx -0.3263,\\ x_{5} \\approx -0.3936\\)." }, { stepNumber: 3, description: "Observe that the iterates alternate above and below \\(\\alpha_{2}\\).", workingLatex: "-0.2 \\to -0.460 \\to -0.288 \\to -0.417 \\to -0.326 \\to \\cdots", explanation: "Each pair brackets \\(\\alpha_{2} \\approx -0.366\\) more tightly than the last — the hallmark of a converging cobweb." }, { stepNumber: 4, description: "Sketch \\(y = x^{2} - 0.5\\) with \\(y = x\\) and trace the cobweb from \\(x_{0} = -0.2\\).", workingLatex: "", explanation: "Vertical segments to the parabola, horizontal segments to the diagonal; the spiral tightens around \\(\\alpha_{2}\\).", diagram: cobwebDiagram((x) => x * x - 0.5, [-1, 0.5], [-1, 0.5], -0.2, 5) }, { stepNumber: 5, description: "State the conclusion.", workingLatex: "", explanation: "Because \\(|g'(\\alpha_{2})| < 1\\), the cobweb converges to the stable fixed point." } ], finalAnswer: "Cobweb converging to \\(\\alpha \\approx -0.366\\)." } },
  { id: "y2nm3-038", topicRef: "y2nm3", topicTitle: "Sketching Iteration 38", difficulty: "Standard", questionText: "Describe the behaviour of \\(x_{n+1} = \\tfrac{5}{x_{n}}\\) starting from \\(x_{0} = 2\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["periodic"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\frac{5}{x}", explanation: "The fixed point satisfies \\(\\alpha = 5/\\alpha\\), i.e.\\ \\(\\alpha^{2} = 5\\)." }, { stepNumber: 2, description: "Solve the fixed-point equation.", workingLatex: "\\alpha = \\sqrt{5} \\approx 2.2361 \\quad (\\text{positive root})", explanation: "There is also a negative fixed point at \\(-\\sqrt{5}\\), but starting from \\(x_{0} = 2 > 0\\) the sequence stays positive." }, { stepNumber: 3, description: "Compute the iterates from \\(x_{0} = 2\\).", workingLatex: "x_{1} = \\frac{5}{2} = 2.5, \\quad x_{2} = \\frac{5}{2.5} = 2, \\quad x_{3} = 2.5, \\ldots", explanation: "The sequence locks into a period-2 cycle \\(\\{2,\\ 2.5\\}\\) immediately." }, { stepNumber: 4, description: "Compute the slope at the fixed point.", workingLatex: "g'(x) = -\\frac{5}{x^{2}}, \\qquad g'(\\sqrt{5}) = -\\frac{5}{5} = -1", explanation: "Borderline case: \\(|g'(\\alpha)| = 1\\), so the convergence criterion fails." }, { stepNumber: 5, description: "Sketch \\(y = 5/x\\) with \\(y = x\\) from \\(x_{0} = 2\\).", workingLatex: "", explanation: "The cobweb traces a perfect rectangle around \\(\\sqrt{5}\\); the diagram never closes inward.", diagram: cobwebDiagram((x) => 5 / x, [1.5, 3], [1.5, 3], 2, 4) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "The sequence cycles between \\(2\\) and \\(2.5\\) forever and does not converge to \\(\\sqrt{5}\\)." } ], finalAnswer: "Cycles between 2 and 2.5; does not converge." } },
  { id: "y2nm3-039", topicRef: "y2nm3", topicTitle: "Sketching Iteration 39", difficulty: "Standard", questionText: "The diagram below shows \\(y = g(x)\\) and \\(y = x\\) with a fixed point at \\(\\alpha \\approx 1\\). The tangent to \\(g\\) at \\(\\alpha\\) has gradient roughly \\(0.7\\). Starting from \\(x_{0} = 0.3\\), describe the iteration's behaviour. Include a sketch.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Read the gradient information from the diagram.", workingLatex: "g'(\\alpha) \\approx 0.7", explanation: "Because \\(0 < g'(\\alpha) < 1\\), \\(\\alpha\\) is attracting and the iteration traces a monotone staircase." }, { stepNumber: 2, description: "Apply the convergence criterion.", workingLatex: "|g'(\\alpha)| \\approx 0.7 < 1", explanation: "Iterates approach \\(\\alpha\\) from one side (no oscillation), shrinking by roughly the factor \\(0.7\\) per step." }, { stepNumber: 3, description: "Use the linear model \\(g(x) = 0.7x + 0.3\\) (gradient \\(0.7\\), fixed point \\(\\alpha = 1\\)) to estimate the iterates from \\(x_{0} = 0.3\\).", workingLatex: "x_{1} = 0.51, \\quad x_{2} = 0.657, \\quad x_{3} = 0.760, \\quad x_{4} \\approx 0.832", explanation: "Each iterate is roughly \\(70\\%\\) of the previous distance to \\(\\alpha = 1\\)." }, { stepNumber: 4, description: "Describe the staircase construction.", workingLatex: "", explanation: "From \\(x_{0}\\) go vertically up to the curve to read \\(x_{1} = g(x_{0})\\); horizontally across to \\(y = x\\) to feed \\(x_{1}\\) back in; repeat. Since the curve lies below \\(y = x\\) for \\(x < \\alpha\\) on this side, iterates rise monotonically." }, { stepNumber: 5, description: "Sketch and conclude.", workingLatex: "", explanation: "The staircase climbs steadily up to \\((1, 1)\\) from the lower-left.", diagram: cobwebDiagram((x) => 0.7 * x + 0.3, [0, 1.2], [0, 1.2], 0.3, 5) } ], finalAnswer: "Monotone staircase converging to \\(\\alpha = 1\\) from below." } },
  { id: "y2nm3-040", topicRef: "y2nm3", topicTitle: "Sketching Iteration 40", difficulty: "Standard", questionText: "Sketch the staircase diagram for \\(x_{n+1} = \\tfrac{1}{3}(x_{n}^{2} + 1)\\) starting from \\(x_{0} = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\frac{x^{2} + 1}{3}", explanation: "Fixed points satisfy \\(3\\alpha = \\alpha^{2} + 1\\), i.e.\\ \\(\\alpha^{2} - 3\\alpha + 1 = 0\\)." }, { stepNumber: 2, description: "Solve the fixed-point quadratic.", workingLatex: "\\alpha = \\frac{3 \\pm \\sqrt{9 - 4}}{2} = \\frac{3 \\pm \\sqrt{5}}{2}", explanation: "Hence \\(\\alpha_{1} = \\displaystyle\\frac{3 - \\sqrt{5}}{2} \\approx 0.3820\\) and \\(\\alpha_{2} = \\displaystyle\\frac{3 + \\sqrt{5}}{2} \\approx 2.6180\\)." }, { stepNumber: 3, description: "Differentiate and classify each fixed point.", workingLatex: "g'(x) = \\frac{2x}{3}", explanation: "\\(g'(\\alpha_{1}) \\approx 0.2546\\) (attracting, staircase); \\(g'(\\alpha_{2}) \\approx 1.7454\\) (repelling)." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 0\\).", workingLatex: "x_{1} = \\frac{1}{3} \\approx 0.3333, \\quad x_{2} \\approx 0.3704, \\quad x_{3} \\approx 0.3791, \\quad x_{4} \\approx 0.3812", explanation: "Iterates rise monotonically toward \\(\\alpha_{1} \\approx 0.3820\\) — a classic staircase." }, { stepNumber: 5, description: "Sketch \\(y = (x^{2} + 1)/3\\) with \\(y = x\\).", workingLatex: "", explanation: "Curve sits above \\(y = x\\) on the left of \\(\\alpha_{1}\\), below it between \\(\\alpha_{1}\\) and \\(\\alpha_{2}\\); the staircase from \\(0\\) climbs to \\(\\alpha_{1}\\).", diagram: cobwebDiagram((x) => (x * x + 1) / 3, [0, 1], [0, 1], 0, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Because \\(|g'(\\alpha_{1})| < 1\\), the staircase converges to \\(\\alpha_{1} \\approx 0.382\\)." } ], finalAnswer: "Staircase converging to \\(\\alpha \\approx 0.382\\)." } },
  { id: "y2nm3-041", topicRef: "y2nm3", topicTitle: "Sketching Iteration 41", difficulty: "Standard", questionText: "For the iteration in Q40, explain what would happen if we started from \\(x_{0} = 3\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the relevant fixed point from Q40.", workingLatex: "\\alpha_{2} = \\frac{3 + \\sqrt{5}}{2} \\approx 2.6180", explanation: "\\(\\alpha_{2}\\) is the larger fixed point of \\(g(x) = (x^{2} + 1)/3\\)." }, { stepNumber: 2, description: "Evaluate \\(g'\\) at \\(\\alpha_{2}\\) to classify.", workingLatex: "g'(\\alpha_{2}) = \\frac{2\\alpha_{2}}{3} = \\frac{3 + \\sqrt{5}}{3} \\approx 1.745", explanation: "Since \\(|g'(\\alpha_{2})| > 1\\), this fixed point is repelling — any nearby start drifts away." }, { stepNumber: 3, description: "Compute iterates from \\(x_{0} = 3\\).", workingLatex: "x_{1} = \\frac{9 + 1}{3} \\approx 3.333, \\quad x_{2} = \\frac{3.333^{2} + 1}{3} \\approx 4.037, \\quad x_{3} \\approx 5.766", explanation: "Each value lies past \\(\\alpha_{2}\\), and the curve \\(y = (x^{2} + 1)/3\\) sits well above \\(y = x\\) there, so the staircase climbs ever higher." }, { stepNumber: 4, description: "Sketch the diverging staircase.", workingLatex: "", explanation: "From \\(x_{0} = 3\\), each vertical step lifts further above \\(y = x\\), and the horizontal step pushes further right.", diagram: cobwebDiagram((x) => (x * x + 1) / 3, [0, 5], [0, 5], 3, 3) }, { stepNumber: 5, description: "Conclude.", workingLatex: "", explanation: "Starting above the unstable threshold \\(\\alpha_{2}\\), iterates escape to \\(+\\infty\\)." } ], finalAnswer: "Staircase diverging to \\(+\\infty\\)." } },
  { id: "y2nm3-042", topicRef: "y2nm3", topicTitle: "Sketching Iteration 42", difficulty: "Standard", questionText: "Sketch the cobweb diagram for the logistic iteration \\(x_{n+1} = 2x_{n}(1 - x_{n})\\) starting from \\(x_{0} = 0.1\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb", "logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = 2x(1 - x)", explanation: "Solve \\(\\alpha = 2\\alpha(1 - \\alpha)\\), i.e.\\ \\(\\alpha = 0\\) or \\(2(1 - \\alpha) = 1\\)." }, { stepNumber: 2, description: "Find the fixed points.", workingLatex: "\\alpha = 0 \\quad \\text{or} \\quad \\alpha = \\frac{1}{2}", explanation: "The non-trivial fixed point is \\(\\alpha = \\tfrac{1}{2}\\)." }, { stepNumber: 3, description: "Differentiate and classify.", workingLatex: "g'(x) = 2 - 4x, \\qquad g'(0) = 2, \\quad g'\\!\\left(\\tfrac{1}{2}\\right) = 0", explanation: "\\(\\alpha = 0\\) is repelling (\\(|g'| = 2 > 1\\)); \\(\\alpha = \\tfrac{1}{2}\\) is super-attracting (\\(g'(\\alpha) = 0\\) gives quadratic convergence)." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 0.1\\).", workingLatex: "x_{1} = 0.18, \\quad x_{2} \\approx 0.2952, \\quad x_{3} \\approx 0.4161, \\quad x_{4} \\approx 0.4859, \\quad x_{5} \\approx 0.4996", explanation: "Convergence is initially slow (far from \\(\\tfrac{1}{2}\\)) then accelerates dramatically once close, because \\(g'(\\tfrac{1}{2}) = 0\\)." }, { stepNumber: 5, description: "Sketch the parabolic curve \\(y = 2x(1 - x)\\) with \\(y = x\\).", workingLatex: "", explanation: "Curve peaks at \\((\\tfrac{1}{2}, \\tfrac{1}{2})\\), touching the diagonal tangentially. From \\(x_{0} = 0.1\\), iterates climb the staircase up to \\((\\tfrac{1}{2}, \\tfrac{1}{2})\\).", diagram: cobwebDiagram((x) => 2 * x * (1 - x), [0, 1], [0, 0.6], 0.1, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Iterates converge rapidly to \\(\\alpha = \\tfrac{1}{2}\\); convergence is quadratic once near the fixed point." } ], finalAnswer: "Staircase converging rapidly to \\(\\alpha = 0.5\\) (quadratic)." } },
  { id: "y2nm3-043", topicRef: "y2nm3", topicTitle: "Sketching Iteration 43", difficulty: "Standard", questionText: "Describe the behaviour of the iteration \\(x_{n+1} = 3.2 x_{n}(1 - x_{n})\\) starting from \\(x_{0} = 0.2\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb", "logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = 3.2\\, x(1 - x)", explanation: "Logistic map with parameter \\(r = 3.2\\), past the period-doubling threshold \\(r = 3\\)." }, { stepNumber: 2, description: "Find the fixed points by solving \\(\\alpha = 3.2\\alpha(1 - \\alpha)\\).", workingLatex: "\\alpha = 0 \\quad \\text{or} \\quad \\alpha = 1 - \\frac{1}{3.2} = \\frac{11}{16} = 0.6875", explanation: "Two fixed points: the trivial \\(0\\) and the non-trivial \\(\\alpha = 0.6875\\)." }, { stepNumber: 3, description: "Differentiate and evaluate at \\(\\alpha = 0.6875\\).", workingLatex: "g'(x) = 3.2(1 - 2x), \\qquad g'(0.6875) = 3.2(1 - 1.375) = -1.2", explanation: "Since \\(|g'(\\alpha)| = 1.2 > 1\\), the non-trivial fixed point is repelling — iterates cannot settle there." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 0.2\\).", workingLatex: "x_{1} = 0.512, \\quad x_{2} \\approx 0.7995, \\quad x_{3} \\approx 0.5129, \\quad x_{4} \\approx 0.7995", explanation: "After a few steps the sequence locks into a period-2 cycle \\(\\{0.5130,\\ 0.7995\\}\\)." }, { stepNumber: 5, description: "Sketch the cobweb.", workingLatex: "", explanation: "The cobweb spirals outward from \\(\\alpha = 0.6875\\) and converges onto a rectangle joining the two period-2 points.", diagram: cobwebDiagram((x) => 3.2 * x * (1 - x), [0, 1], [0, 0.9], 0.2, 10) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Because \\(|g'(\\alpha)| > 1\\), the fixed point is unstable; the long-run behaviour is a 2-cycle, not a convergent sequence." } ], finalAnswer: "Period-2 oscillation — cobweb does not converge." } },
  { id: "y2nm3-044", topicRef: "y2nm3", topicTitle: "Sketching Iteration 44", difficulty: "Standard", questionText: "Sketch the diagram for \\(x_{n+1} = \\tfrac{1}{2}\\!\\left(x_{n} + \\tfrac{3}{x_{n}}\\right)\\) starting from \\(x_{0} = 3\\). Explain why convergence is so rapid.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase", "babylonian"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\frac{1}{2}\\!\\left(x + \\frac{3}{x}\\right)", explanation: "This is the Babylonian (Heron) iteration for \\(\\sqrt{3}\\)." }, { stepNumber: 2, description: "Find the fixed point by solving \\(\\alpha = g(\\alpha)\\).", workingLatex: "2\\alpha = \\alpha + \\frac{3}{\\alpha} \\Rightarrow \\alpha^{2} = 3 \\Rightarrow \\alpha = \\sqrt{3}", explanation: "Only the positive root is reached from \\(x_{0} = 3 > 0\\)." }, { stepNumber: 3, description: "Differentiate and evaluate at \\(\\alpha = \\sqrt{3}\\).", workingLatex: "g'(x) = \\frac{1}{2}\\!\\left(1 - \\frac{3}{x^{2}}\\right), \\qquad g'(\\sqrt{3}) = \\frac{1}{2}(1 - 1) = 0", explanation: "Because \\(g'(\\alpha) = 0\\), the linear convergence factor vanishes — the iteration enjoys quadratic convergence, roughly doubling the number of correct digits each step." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 3\\).", workingLatex: "x_{1} = \\frac{1}{2}\\!\\left(3 + 1\\right) = 2, \\quad x_{2} = \\frac{1}{2}\\!\\left(2 + 1.5\\right) = 1.75, \\quad x_{3} \\approx 1.7321", explanation: "Compare \\(\\sqrt{3} \\approx 1.7320508\\): \\(x_{3}\\) already matches to four decimal places." }, { stepNumber: 5, description: "Sketch \\(y = g(x)\\) and \\(y = x\\).", workingLatex: "", explanation: "The curve is tangent to \\(y = x\\) at \\((\\sqrt{3}, \\sqrt{3})\\); the staircase from \\(3\\) drops swiftly onto the fixed point.", diagram: cobwebDiagram((x) => 0.5 * (x + 3 / x), [1, 3.5], [1, 3.5], 3, 3) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "The tangent at \\(\\sqrt{3}\\) is horizontal, so the iteration is super-attracting; convergence is quadratic." } ], finalAnswer: "Staircase jumps almost immediately to \\(\\sqrt{3} \\approx 1.732\\)." } },
  { id: "y2nm3-045", topicRef: "y2nm3", topicTitle: "Sketching Iteration 45", difficulty: "Standard", questionText: "For the iteration \\(x_{n+1} = 0.4 x_{n} + 3\\) starting from \\(x_{0} = 0\\), state the fixed point and sketch the staircase.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase", "linear"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = 0.4x + 3", explanation: "A linear iteration: the slope of \\(g\\) is constant, equal to \\(0.4\\)." }, { stepNumber: 2, description: "Solve the fixed-point equation \\(\\alpha = 0.4\\alpha + 3\\).", workingLatex: "0.6\\alpha = 3 \\Rightarrow \\alpha = 5", explanation: "Curve and diagonal intersect at \\((5, 5)\\)." }, { stepNumber: 3, description: "Classify the behaviour.", workingLatex: "g'(\\alpha) = 0.4, \\qquad 0 < g'(\\alpha) < 1", explanation: "Staircase converging monotonically; each iterate covers \\(60\\%\\) of the remaining gap to \\(\\alpha = 5\\)." }, { stepNumber: 4, description: "Compute the iterates from \\(x_{0} = 0\\).", workingLatex: "x_{1} = 3.00, \\quad x_{2} = 4.20, \\quad x_{3} = 4.68, \\quad x_{4} = 4.872, \\quad x_{5} \\approx 4.9488", explanation: "Values rise steadily toward \\(\\alpha = 5\\)." }, { stepNumber: 5, description: "Sketch the staircase.", workingLatex: "", explanation: "Plot \\(y = 0.4x + 3\\) and \\(y = x\\). From \\((0, 0)\\), step up to the line, across to \\(y = x\\), repeat — staircase climbs to \\((5, 5)\\).", diagram: cobwebDiagram((x) => 0.4 * x + 3, [0, 6], [0, 6], 0, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Staircase converges monotonically from below to \\(\\alpha = 5\\)." } ], finalAnswer: "Staircase converging to \\(\\alpha = 5\\)." } },
  { id: "y2nm3-046", topicRef: "y2nm3", topicTitle: "Sketching Iteration 46", difficulty: "Standard", questionText: "Sketch \\(y = \\sin x\\) and \\(y = x\\) together and explain why the only fixed point of \\(x_{n+1} = \\sin x_{n}\\) is \\(x = 0\\), and show that it is a borderline case.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["concept", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\sin x", explanation: "Fixed points satisfy \\(\\sin \\alpha = \\alpha\\)." }, { stepNumber: 2, description: "Compare \\(\\sin x\\) with \\(x\\) using the inequality \\(|\\sin x| \\le |x|\\).", workingLatex: "\\sin x < x \\ \\text{for } x > 0; \\quad \\sin x > x \\ \\text{for } x < 0", explanation: "Equality holds only at \\(x = 0\\), so the only solution of \\(\\sin x = x\\) is \\(\\alpha = 0\\)." }, { stepNumber: 3, description: "Differentiate and evaluate at the fixed point.", workingLatex: "g'(x) = \\cos x, \\qquad g'(0) = \\cos 0 = 1", explanation: "This is the borderline case \\(|g'(\\alpha)| = 1\\): the convergence criterion neither succeeds nor fails outright." }, { stepNumber: 4, description: "Examine the second-order behaviour.", workingLatex: "\\sin x \\approx x - \\frac{x^{3}}{6}", explanation: "Near \\(0\\), iterates shrink by roughly \\(x_{n+1} \\approx x_{n} - x_{n}^{3}/6\\) — they converge to \\(0\\), but extremely slowly (sub-linearly)." }, { stepNumber: 5, description: "Trace a few iterates from \\(x_{0} = 0.8\\) (radians).", workingLatex: "x_{1} = \\sin 0.8 \\approx 0.7174, \\quad x_{2} \\approx 0.6570, \\quad x_{3} \\approx 0.6111", explanation: "Each step reduces the magnitude by a tiny amount; in 100 iterations \\(x_{n}\\) is still around \\(0.17\\).", diagram: cobwebDiagram((x) => Math.sin(x), [-1, 1], [-1, 1], 0.8, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Only fixed point is \\(\\alpha = 0\\). Because \\(g'(0) = 1\\), convergence is borderline and extremely slow." } ], finalAnswer: "Only fixed point is \\(x = 0\\); \\(g'(0) = 1\\) so convergence is extremely slow." } },
  { id: "y2nm3-047", topicRef: "y2nm3", topicTitle: "Sketching Iteration 47", difficulty: "Standard", questionText: "Sketch the staircase diagram for \\(x_{n+1} = \\tfrac{1}{4}(x_{n}^{2} + 3)\\) starting from \\(x_{0} = 0.5\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\frac{x^{2} + 3}{4}", explanation: "Fixed points satisfy \\(4\\alpha = \\alpha^{2} + 3\\), i.e.\\ \\(\\alpha^{2} - 4\\alpha + 3 = 0\\)." }, { stepNumber: 2, description: "Solve the fixed-point quadratic.", workingLatex: "(\\alpha - 1)(\\alpha - 3) = 0 \\Rightarrow \\alpha = 1 \\text{ or } 3", explanation: "Two real fixed points." }, { stepNumber: 3, description: "Differentiate and classify each fixed point.", workingLatex: "g'(x) = \\frac{x}{2}, \\qquad g'(1) = \\frac{1}{2}, \\quad g'(3) = \\frac{3}{2}", explanation: "\\(\\alpha = 1\\) is attracting (staircase, \\(|g'| < 1\\)); \\(\\alpha = 3\\) is repelling." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 0.5\\).", workingLatex: "x_{1} = \\frac{0.25 + 3}{4} \\approx 0.8125, \\quad x_{2} \\approx 0.9150, \\quad x_{3} \\approx 0.9593, \\quad x_{4} \\approx 0.9801", explanation: "Iterates close in monotonically on \\(\\alpha = 1\\)." }, { stepNumber: 5, description: "Sketch the parabola \\(y = (x^{2} + 3)/4\\) with \\(y = x\\).", workingLatex: "", explanation: "Curve dips below \\(y = x\\) between the fixed points and rises steeply outside; staircase from \\(0.5\\) climbs toward \\((1, 1)\\).", diagram: cobwebDiagram((x) => (x * x + 3) / 4, [0, 1.8], [0, 1.8], 0.5, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Because \\(|g'(1)| = 0.5 < 1\\), the staircase converges to \\(\\alpha = 1\\)." } ], finalAnswer: "Staircase converging to \\(\\alpha = 1\\)." } },
  { id: "y2nm3-048", topicRef: "y2nm3", topicTitle: "Sketching Iteration 48", difficulty: "Standard", questionText: "Use the sketched iteration in Q47 to estimate, to 1 decimal place, the value of \\(x_{3}\\) when \\(x_{0} = 0.5\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the iteration formula.", workingLatex: "x_{n+1} = \\frac{x_{n}^{2} + 3}{4}", explanation: "Same iteration as Q47 with \\(x_{0} = 0.5\\)." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\frac{0.5^{2} + 3}{4} = \\frac{3.25}{4} = 0.8125", explanation: "Plug \\(x_{0} = 0.5\\) into \\(g\\)." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\frac{0.8125^{2} + 3}{4} = \\frac{3.6602}{4} \\approx 0.9150", explanation: "Iterate once more." }, { stepNumber: 4, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\frac{0.9150^{2} + 3}{4} = \\frac{3.8373}{4} \\approx 0.9593", explanation: "Apply \\(g\\) again." }, { stepNumber: 5, description: "Read off the result to 1 decimal place using the staircase sketch.", workingLatex: "x_{3} \\approx 1.0", explanation: "The staircase has nearly reached \\(\\alpha = 1\\).", diagram: cobwebDiagram((x) => (x * x + 3) / 4, [0, 1.8], [0, 1.8], 0.5, 3) } ], finalAnswer: "\\(x_{3} \\approx 1.0\\) (to 1 d.p.)." } },
  { id: "y2nm3-049", topicRef: "y2nm3", topicTitle: "Sketching Iteration 49", difficulty: "Standard", questionText: "Sketch and describe the behaviour of \\(x_{n+1} = 3\\sqrt{x_{n}} - 2\\) starting from \\(x_{0} = 2\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = 3\\sqrt{x} - 2", explanation: "Solve \\(\\alpha = 3\\sqrt{\\alpha} - 2\\), i.e.\\ let \\(u = \\sqrt{\\alpha}\\) so \\(u^{2} - 3u + 2 = 0\\)." }, { stepNumber: 2, description: "Factorise and solve for \\(u\\), then for \\(\\alpha\\).", workingLatex: "(u - 1)(u - 2) = 0 \\Rightarrow u = 1, 2 \\Rightarrow \\alpha = 1, 4", explanation: "Two fixed points." }, { stepNumber: 3, description: "Differentiate and classify each fixed point.", workingLatex: "g'(x) = \\frac{3}{2\\sqrt{x}}, \\qquad g'(1) = \\frac{3}{2}, \\quad g'(4) = \\frac{3}{4}", explanation: "\\(\\alpha = 1\\) repelling (\\(|g'| > 1\\)); \\(\\alpha = 4\\) attracting (\\(|g'| < 1\\)) with staircase behaviour." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 2\\).", workingLatex: "x_{1} = 3\\sqrt{2} - 2 \\approx 2.2426, \\quad x_{2} \\approx 2.4926, \\quad x_{3} \\approx 2.7364, \\quad x_{4} \\approx 2.9626, \\quad x_{5} \\approx 3.1637", explanation: "Iterates rise monotonically toward \\(\\alpha = 4\\)." }, { stepNumber: 5, description: "Sketch the curve \\(y = 3\\sqrt{x} - 2\\) with \\(y = x\\).", workingLatex: "", explanation: "Curve crosses \\(y = x\\) at \\((1, 1)\\) and \\((4, 4)\\). The staircase from \\(x_{0} = 2\\) climbs steadily toward the stable fixed point.", diagram: cobwebDiagram((x) => 3 * Math.sqrt(x) - 2, [0.5, 5], [0.5, 5], 2, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Iterates form a monotone staircase that converges to \\(\\alpha = 4\\)." } ], finalAnswer: "Staircase converging to \\(\\alpha = 4\\)." } },
  { id: "y2nm3-050", topicRef: "y2nm3", topicTitle: "Sketching Iteration 50", difficulty: "Standard", questionText: "Give an example of an iteration \\(x_{n+1} = g(x_{n})\\) whose diagram is a diverging staircase. State the fixed point and the slope of \\(g\\) there.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["example", "divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall when a staircase diverges.", workingLatex: "g'(\\alpha) > 1", explanation: "A positive slope greater than \\(1\\) gives a monotonic staircase that grows away from \\(\\alpha\\)." }, { stepNumber: 2, description: "Construct a simple linear example.", workingLatex: "g(x) = 1.5\\,x - 0.5", explanation: "Linear iteration with constant slope \\(1.5 > 1\\)." }, { stepNumber: 3, description: "Locate the fixed point.", workingLatex: "\\alpha = 1.5\\alpha - 0.5 \\Rightarrow 0.5\\alpha = 0.5 \\Rightarrow \\alpha = 1", explanation: "" }, { stepNumber: 4, description: "Confirm the slope at \\(\\alpha\\).", workingLatex: "g'(x) = 1.5, \\qquad g'(\\alpha) = 1.5 > 1", explanation: "Repelling fixed point — small departures from \\(\\alpha\\) grow by a factor \\(1.5\\) per iteration." }, { stepNumber: 5, description: "Iterate from \\(x_{0} = 1.1\\) to demonstrate divergence.", workingLatex: "x_{1} = 1.15, \\quad x_{2} = 1.225, \\quad x_{3} = 1.3375, \\quad x_{4} \\approx 1.5063", explanation: "Each iterate is further from \\(\\alpha = 1\\) than the previous." }, { stepNumber: 6, description: "Sketch the diverging staircase.", workingLatex: "", explanation: "Curve steeper than the diagonal at \\(\\alpha\\); staircase climbs away from \\((1, 1)\\).", diagram: cobwebDiagram((x) => 1.5 * x - 0.5, [0.6, 2.2], [0.6, 2.2], 1.1, 3) } ], finalAnswer: "Example: \\(x_{n+1} = 1.5 x_{n} - 0.5\\); fixed point \\(\\alpha = 1\\), slope \\(1.5\\)." } },
  { id: "y2nm3-051", topicRef: "y2nm3", topicTitle: "Sketching Iteration 51", difficulty: "Standard", questionText: "Give an example of an iteration \\(x_{n+1} = g(x_{n})\\) whose diagram is a diverging cobweb.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["example", "divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall when a cobweb diverges.", workingLatex: "g'(\\alpha) < -1", explanation: "Negative slope with magnitude exceeding \\(1\\) gives an outward-spiralling cobweb." }, { stepNumber: 2, description: "Construct a simple linear example.", workingLatex: "g(x) = -2x + 3", explanation: "Linear iteration with constant slope \\(-2\\)." }, { stepNumber: 3, description: "Locate the fixed point.", workingLatex: "\\alpha = -2\\alpha + 3 \\Rightarrow 3\\alpha = 3 \\Rightarrow \\alpha = 1", explanation: "" }, { stepNumber: 4, description: "Confirm the slope at \\(\\alpha\\).", workingLatex: "g'(x) = -2, \\qquad g'(\\alpha) = -2", explanation: "\\(|g'(\\alpha)| = 2 > 1\\) and negative, so iterates jump alternate sides of \\(\\alpha\\) and grow further away." }, { stepNumber: 5, description: "Iterate from \\(x_{0} = 1.1\\) to demonstrate divergence.", workingLatex: "x_{1} = 0.8, \\quad x_{2} = 1.4, \\quad x_{3} = 0.2, \\quad x_{4} = 2.6", explanation: "Sign-alternating departure from \\(\\alpha = 1\\); the gap doubles in magnitude each step." }, { stepNumber: 6, description: "Sketch the diverging cobweb.", workingLatex: "", explanation: "Curve has negative slope steeper than \\(-1\\); cobweb spirals outward from \\((1, 1)\\).", diagram: cobwebDiagram((x) => -2 * x + 3, [0.5, 1.8], [0.5, 1.8], 1.1, 2) } ], finalAnswer: "Example: \\(x_{n+1} = -2 x_{n} + 3\\); fixed point \\(\\alpha = 1\\), slope \\(-2\\)." } },
  { id: "y2nm3-052", topicRef: "y2nm3", topicTitle: "Sketching Iteration 52", difficulty: "Standard", questionText: "Sketch the cobweb for \\(x_{n+1} = \\tfrac{1}{x_{n} + 1}\\) starting from \\(x_{0} = 0.5\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\frac{1}{x + 1}", explanation: "Fixed points satisfy \\(\\alpha(\\alpha + 1) = 1\\), i.e.\\ \\(\\alpha^{2} + \\alpha - 1 = 0\\)." }, { stepNumber: 2, description: "Solve the fixed-point quadratic.", workingLatex: "\\alpha = \\frac{-1 \\pm \\sqrt{5}}{2}", explanation: "Take the positive root: \\(\\alpha = \\displaystyle\\frac{-1 + \\sqrt{5}}{2} \\approx 0.6180\\) (the reciprocal of the golden ratio)." }, { stepNumber: 3, description: "Differentiate and evaluate at \\(\\alpha\\).", workingLatex: "g'(x) = -\\frac{1}{(x + 1)^{2}}, \\qquad g'(\\alpha) = -\\frac{1}{(\\alpha + 1)^{2}} = -\\alpha^{2} \\approx -0.3820", explanation: "Since \\(-1 < g'(\\alpha) < 0\\), iterates form a converging cobweb." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 0.5\\).", workingLatex: "x_{1} = \\frac{1}{1.5} \\approx 0.6667, \\quad x_{2} = \\frac{1}{1.6667} \\approx 0.6000, \\quad x_{3} \\approx 0.6250, \\quad x_{4} \\approx 0.6154, \\quad x_{5} \\approx 0.6190", explanation: "Iterates alternate above and below \\(\\alpha\\), closing in on \\(0.6180\\)." }, { stepNumber: 5, description: "Sketch the curve \\(y = 1/(x + 1)\\) with \\(y = x\\).", workingLatex: "", explanation: "Decreasing hyperbolic curve crosses \\(y = x\\) at \\(\\alpha\\); cobweb spirals inward.", diagram: cobwebDiagram((x) => 1 / (x + 1), [0, 1.2], [0, 1.2], 0.5, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Because \\(|g'(\\alpha)| \\approx 0.382 < 1\\), the cobweb converges to \\(\\alpha \\approx 0.6180\\)." } ], finalAnswer: "Cobweb converging to \\(\\alpha \\approx 0.618\\)." } },
  { id: "y2nm3-053", topicRef: "y2nm3", topicTitle: "Sketching Iteration 53", difficulty: "Challenge", questionText: "On a single sketch, show \\(y = x^{3}\\) and \\(y = x\\). State the fixed points and use the slope of \\(g\\) at each to classify the behaviour of \\(x_{n+1} = x_{n}^{3}\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["classification"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = x^{3}", explanation: "Solve \\(\\alpha^{3} = \\alpha\\), i.e.\\ \\(\\alpha(\\alpha^{2} - 1) = 0\\)." }, { stepNumber: 2, description: "Find the fixed points.", workingLatex: "\\alpha = 0, \\quad \\alpha = 1, \\quad \\alpha = -1", explanation: "Three real fixed points where \\(y = x^{3}\\) cuts \\(y = x\\)." }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = 3x^{2}", explanation: "We will evaluate \\(g'\\) at each fixed point." }, { stepNumber: 4, description: "Classify each fixed point.", workingLatex: "g'(0) = 0, \\qquad g'(\\pm 1) = 3", explanation: "\\(\\alpha = 0\\): super-attracting (\\(|g'| = 0 < 1\\); convergence is cubic in this case). \\(\\alpha = \\pm 1\\): repelling (\\(|g'| = 3 > 1\\)), iterates flee." }, { stepNumber: 5, description: "Describe the qualitative behaviour by region.", workingLatex: "|x_{0}| < 1 \\Rightarrow x_{n} \\to 0; \\quad |x_{0}| > 1 \\Rightarrow x_{n} \\to \\pm\\infty", explanation: "Inside the unit interval, cubing shrinks; outside, cubing blows up." }, { stepNumber: 6, description: "Sketch \\(y = x^{3}\\) with \\(y = x\\) and indicate one trajectory.", workingLatex: "", explanation: "Curve cuts the diagonal at \\(0, \\pm 1\\). From \\(x_{0} = 0.8\\), iterates collapse rapidly to \\(0\\).", diagram: cobwebDiagram((x) => x * x * x, [-1.2, 1.2], [-1.2, 1.2], 0.8, 4) } ], finalAnswer: "\\(x = 0\\) stable; \\(x = \\pm 1\\) unstable." } },
  { id: "y2nm3-054", topicRef: "y2nm3", topicTitle: "Sketching Iteration 54", difficulty: "Challenge", questionText: "Sketch the diagram for \\(x_{n+1} = x_{n}^{3}\\) starting from \\(x_{0} = 0.9\\) and describe what happens.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the relevant fixed points from Q53.", workingLatex: "\\alpha = 0 \\ (\\text{attracting}), \\quad \\alpha = 1 \\ (\\text{repelling})", explanation: "Starting from \\(x_{0} = 0.9 \\in (0, 1)\\), we are below the unstable point \\(1\\) and above the stable point \\(0\\)." }, { stepNumber: 2, description: "Observe that cubing shrinks values strictly inside \\((-1, 1)\\).", workingLatex: "|x_{n}| < 1 \\Rightarrow |x_{n+1}| = |x_{n}|^{3} < |x_{n}|", explanation: "Each iterate is smaller in magnitude than the last, since \\(|x|^{3} < |x|\\) when \\(|x| < 1\\)." }, { stepNumber: 3, description: "Compute iterates from \\(x_{0} = 0.9\\).", workingLatex: "x_{1} = 0.729, \\quad x_{2} \\approx 0.3874, \\quad x_{3} \\approx 0.0582, \\quad x_{4} \\approx 0.000197, \\quad x_{5} \\approx 7.6 \\times 10^{-12}", explanation: "Convergence is initially slow (factor close to \\(0.81\\) for the first step) then super-fast as iterates approach \\(0\\), reflecting \\(g'(0) = 0\\)." }, { stepNumber: 4, description: "Sketch the curve \\(y = x^{3}\\) and the diagonal \\(y = x\\).", workingLatex: "", explanation: "Curve lies below \\(y = x\\) for \\(0 < x < 1\\); staircase from \\(0.9\\) descends rapidly toward \\((0, 0)\\).", diagram: cobwebDiagram((x) => x * x * x, [-0.2, 1.05], [-0.2, 1.05], 0.9, 5) }, { stepNumber: 5, description: "Conclude.", workingLatex: "", explanation: "Monotone staircase converging to the stable fixed point \\(\\alpha = 0\\); convergence is cubic near the origin." } ], finalAnswer: "Staircase converging to the stable fixed point \\(0\\)." } },
  { id: "y2nm3-055", topicRef: "y2nm3", topicTitle: "Sketching Iteration 55", difficulty: "Challenge", questionText: "Sketch the diagram for \\(x_{n+1} = x_{n}^{3}\\) starting from \\(x_{0} = 1.1\\). Describe the behaviour.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["divergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the relevant fixed point.", workingLatex: "\\alpha = 1 \\quad \\text{with} \\quad g'(1) = 3 > 1", explanation: "From Q53 the unstable fixed point at \\(1\\) repels nearby iterates." }, { stepNumber: 2, description: "Observe \\(|x_{0}| > 1\\) implies divergence.", workingLatex: "|x| > 1 \\Rightarrow |x|^{3} > |x|", explanation: "Cubing magnifies values outside the unit interval." }, { stepNumber: 3, description: "Compute the first few iterates.", workingLatex: "x_{1} = 1.331, \\quad x_{2} \\approx 2.358, \\quad x_{3} \\approx 13.110, \\quad x_{4} \\approx 2253", explanation: "Growth accelerates very quickly." }, { stepNumber: 4, description: "Sketch and interpret.", workingLatex: "", explanation: "On \\(y = x^{3}\\) past \\((1, 1)\\), the curve lies steeply above \\(y = x\\); the staircase from \\(x_{0} = 1.1\\) climbs explosively.", diagram: cobwebDiagram((x) => x * x * x, [0.95, 2.5], [0.95, 2.5], 1.1, 2) }, { stepNumber: 5, description: "Conclude.", workingLatex: "", explanation: "Staircase diverges to \\(+\\infty\\); iterates double their distance from \\(\\alpha = 1\\) roughly every step initially, then explode." } ], finalAnswer: "Staircase diverging to \\(+\\infty\\)." } },
  { id: "y2nm3-056", topicRef: "y2nm3", topicTitle: "Sketching Iteration 56", difficulty: "Challenge", questionText: "A diagram shows \\(y = g(x)\\) cutting \\(y = x\\) at two points \\(\\alpha_{1} < \\alpha_{2}\\). The slope of \\(g\\) at \\(\\alpha_{1}\\) is \\(0.5\\), and at \\(\\alpha_{2}\\) is \\(1.8\\). Describe the behaviour of the iteration starting from a point just below \\(\\alpha_{1}\\), between \\(\\alpha_{1}\\) and \\(\\alpha_{2}\\), and just above \\(\\alpha_{2}\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["stability"], workedSolution: { steps: [ { stepNumber: 1, description: "Classify the two fixed points using the given slopes.", workingLatex: "|g'(\\alpha_{1})| = 0.5 < 1 \\ (\\text{attracting}); \\quad |g'(\\alpha_{2})| = 1.8 > 1 \\ (\\text{repelling})", explanation: "\\(\\alpha_{1}\\) attracts nearby iterates; \\(\\alpha_{2}\\) repels them." }, { stepNumber: 2, description: "Region just below \\(\\alpha_{1}\\).", workingLatex: "", explanation: "Slope \\(0.5\\) is positive and small, so iterates step monotonically upward toward \\(\\alpha_{1}\\) — a converging staircase." }, { stepNumber: 3, description: "Region between \\(\\alpha_{1}\\) and \\(\\alpha_{2}\\).", workingLatex: "", explanation: "Iterates remain inside the basin of attraction of \\(\\alpha_{1}\\): the staircase walks back down to \\(\\alpha_{1}\\) (since \\(g(x) > x\\) is impossible without crossing \\(\\alpha_{2}\\) again, so \\(g(x) < x\\) in this strip when the standard exam picture is intended)." }, { stepNumber: 4, description: "Region just above \\(\\alpha_{2}\\).", workingLatex: "", explanation: "Slope \\(1.8 > 1\\) gives a diverging staircase: iterates climb past the unstable threshold and escape to \\(+\\infty\\)." }, { stepNumber: 5, description: "Identify \\(\\alpha_{2}\\) as a basin boundary.", workingLatex: "x_{0} < \\alpha_{2} \\Rightarrow x_{n} \\to \\alpha_{1}, \\quad x_{0} > \\alpha_{2} \\Rightarrow x_{n} \\to +\\infty", explanation: "\\(\\alpha_{2}\\) is the watershed: starts below it fall into the well at \\(\\alpha_{1}\\); starts above it escape." }, { stepNumber: 6, description: "Sketch a representative quadratic \\(g(x) = (x^{2}+3)/4\\) (same slopes \\(0.5\\) at \\(1\\), \\(1.5\\) at \\(3\\)) to illustrate.", workingLatex: "", explanation: "From \\(x_{0} = 0.5\\) we see the staircase climb to \\(\\alpha_{1} = 1\\); a hypothetical start past \\(\\alpha_{2} = 3\\) would diverge.", diagram: cobwebDiagram((x) => (x * x + 3) / 4, [0, 3.5], [0, 3.5], 0.5, 5) } ], finalAnswer: "Stable \\(\\alpha_{1}\\) attracts nearby iterates; \\(\\alpha_{2}\\) is a threshold above which the iteration escapes." } },
  { id: "y2nm3-057", topicRef: "y2nm3", topicTitle: "Sketching Iteration 57", difficulty: "Challenge", questionText: "For the iteration \\(x_{n+1} = g(x_{n})\\) with \\(g(x) = 1 + \\tfrac{1}{x^{2}}\\), sketch the cobweb starting from \\(x_{0} = 1\\). State the equation satisfied by the fixed point.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["cobweb"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = 1 + \\frac{1}{x^{2}}", explanation: "Solve \\(\\alpha = 1 + 1/\\alpha^{2}\\), i.e.\\ multiply by \\(\\alpha^{2}\\)." }, { stepNumber: 2, description: "Derive the fixed-point cubic.", workingLatex: "\\alpha^{3} = \\alpha^{2} + 1 \\Rightarrow \\alpha^{3} - \\alpha^{2} - 1 = 0", explanation: "Real root \\(\\alpha \\approx 1.4656\\) (verifiable numerically)." }, { stepNumber: 3, description: "Differentiate and evaluate at \\(\\alpha\\).", workingLatex: "g'(x) = -\\frac{2}{x^{3}}, \\qquad g'(\\alpha) = -\\frac{2}{\\alpha^{3}} \\approx -0.636", explanation: "Since \\(\\alpha^{3} = \\alpha^{2} + 1 \\approx 3.148\\), we get \\(g'(\\alpha) \\approx -2/3.148 \\approx -0.636\\). \\(-1 < g'(\\alpha) < 0\\): converging cobweb." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 1\\).", workingLatex: "x_{1} = 2, \\quad x_{2} = 1.25, \\quad x_{3} = 1.64, \\quad x_{4} \\approx 1.372, \\quad x_{5} \\approx 1.531", explanation: "Iterates oscillate either side of \\(\\alpha\\), closing in slowly because \\(|g'| \\approx 0.64\\)." }, { stepNumber: 5, description: "Sketch the curve \\(y = 1 + 1/x^{2}\\) with \\(y = x\\).", workingLatex: "", explanation: "Curve decreasing for \\(x > 0\\), crossing the diagonal at \\(\\alpha\\); cobweb spirals inward to \\(\\alpha \\approx 1.4656\\).", diagram: cobwebDiagram((x) => 1 + 1 / (x * x), [0.8, 2.2], [0.8, 2.2], 1, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Cobweb converging to the real root \\(\\alpha \\approx 1.4656\\) of \\(\\alpha^{3} - \\alpha^{2} - 1 = 0\\)." } ], finalAnswer: "Cobweb converging to \\(\\alpha \\approx 1.4656\\); \\(\\alpha^{3} - \\alpha^{2} - 1 = 0\\)." } },
  { id: "y2nm3-058", topicRef: "y2nm3", topicTitle: "Sketching Iteration 58", difficulty: "Challenge", questionText: "On axes, sketch both \\(y = g(x) = 1 - x^{2}\\) and \\(y = x\\). Identify the fixed points and classify each.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["classification"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = 1 - x^{2}", explanation: "Solve \\(\\alpha = 1 - \\alpha^{2}\\), i.e.\\ \\(\\alpha^{2} + \\alpha - 1 = 0\\)." }, { stepNumber: 2, description: "Solve the fixed-point quadratic.", workingLatex: "\\alpha = \\frac{-1 \\pm \\sqrt{5}}{2}", explanation: "So \\(\\alpha_{1} = \\displaystyle\\frac{-1 + \\sqrt{5}}{2} \\approx 0.6180\\) and \\(\\alpha_{2} = \\displaystyle\\frac{-1 - \\sqrt{5}}{2} \\approx -1.6180\\)." }, { stepNumber: 3, description: "Differentiate and evaluate at each fixed point.", workingLatex: "g'(x) = -2x, \\qquad g'(\\alpha_{1}) \\approx -1.236, \\quad g'(\\alpha_{2}) \\approx 3.236", explanation: "" }, { stepNumber: 4, description: "Apply \\(|g'(\\alpha)| < 1\\) to classify.", workingLatex: "|g'(\\alpha_{1})| \\approx 1.236 > 1, \\quad |g'(\\alpha_{2})| \\approx 3.236 > 1", explanation: "Both fixed points are repelling — neither attracts iterates under simple fixed-point iteration." }, { stepNumber: 5, description: "Sketch \\(y = 1 - x^{2}\\) (downward parabola) and \\(y = x\\).", workingLatex: "", explanation: "The line cuts the parabola at \\(\\alpha_{1}\\) and \\(\\alpha_{2}\\). Starting from \\(x_{0} = 0.5\\), iterates jump between \\(0.75,\\ 0.4375,\\ 0.8086, \\ldots\\) and fail to settle.", diagram: cobwebDiagram((x) => 1 - x * x, [-2, 2], [-2, 2], 0.5, 4) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Both fixed points are unstable; the iteration cannot converge directly. A rearrangement (e.g.\\ \\(x = \\sqrt{1 - x}\\)) would be needed in practice." } ], finalAnswer: "Both fixed points are unstable." } },
  { id: "y2nm3-059", topicRef: "y2nm3", topicTitle: "Sketching Iteration 59", difficulty: "Challenge", questionText: "Given the iteration \\(x_{n+1} = \\tfrac{x_{n}^{2} + a}{b x_{n}}\\) for positive constants \\(a,\\ b\\), find the fixed points and the condition on \\(g'(\\alpha)\\) for convergence.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["theory"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\frac{x^{2} + a}{b\\, x}", explanation: "Set \\(g(\\alpha) = \\alpha\\) and clear the denominator." }, { stepNumber: 2, description: "Derive the fixed-point equation.", workingLatex: "\\alpha = \\frac{\\alpha^{2} + a}{b\\, \\alpha} \\Rightarrow b\\,\\alpha^{2} = \\alpha^{2} + a \\Rightarrow (b - 1)\\,\\alpha^{2} = a", explanation: "Real positive fixed points require \\(b > 1\\)." }, { stepNumber: 3, description: "Solve for \\(\\alpha\\).", workingLatex: "\\alpha = \\sqrt{\\frac{a}{b - 1}} \\quad (b > 1)", explanation: "The positive root is the physically meaningful one for the typical \\(a, b > 0\\) setting." }, { stepNumber: 4, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\frac{x}{b} + \\frac{a}{b\\, x} \\Rightarrow g'(x) = \\frac{1}{b}\\!\\left(1 - \\frac{a}{x^{2}}\\right)", explanation: "Splitting the fraction makes differentiation routine." }, { stepNumber: 5, description: "Evaluate \\(g'\\) at the fixed point.", workingLatex: "g'(\\alpha) = \\frac{1}{b}\\!\\left(1 - \\frac{a}{a/(b-1)}\\right) = \\frac{1}{b}\\bigl(1 - (b - 1)\\bigr) = \\frac{2 - b}{b}", explanation: "Substitute \\(\\alpha^{2} = a/(b - 1)\\)." }, { stepNumber: 6, description: "Apply the convergence criterion \\(|g'(\\alpha)| < 1\\).", workingLatex: "\\left|\\frac{2 - b}{b}\\right| < 1 \\Rightarrow -b < 2 - b < b \\Rightarrow b > 1", explanation: "For \\(b > 1\\), \\(|2 - b|/b < 1\\) holds. (Note: \\(b = 2\\) gives \\(g'(\\alpha) = 0\\), the Babylonian super-attracting case.)" }, { stepNumber: 7, description: "Illustrate with \\(a = 3,\\ b = 2\\) (so \\(\\alpha = \\sqrt{3}\\)).", workingLatex: "g(x) = \\frac{x^{2} + 3}{2x} = \\frac{1}{2}\\!\\left(x + \\frac{3}{x}\\right)", explanation: "This is the Babylonian iteration for \\(\\sqrt{3}\\) (cf.\\ Q44); \\(g'(\\sqrt{3}) = 0\\), quadratic convergence.", diagram: cobwebDiagram((x) => (x * x + 3) / (2 * x), [1, 3.5], [1, 3.5], 3, 3) } ], finalAnswer: "Fixed points exist when \\(b > 1\\); convergence guaranteed when \\(b > 1\\)." } },
  { id: "y2nm3-060", topicRef: "y2nm3", topicTitle: "Sketching Iteration 60", difficulty: "Challenge", questionText: "Sketch the staircase for \\(x_{n+1} = \\tfrac{1}{2}(x_{n} + \\tfrac{10}{x_{n}})\\) starting from \\(x_{0} = 1\\). Compute \\(x_{1},\\ x_{2}\\) to 4 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["babylonian", "staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the iteration.", workingLatex: "g(x) = \\frac{1}{2}\\!\\left(x + \\frac{10}{x}\\right)", explanation: "Babylonian iteration for \\(\\sqrt{10}\\); fixed point \\(\\alpha = \\sqrt{10} \\approx 3.1623\\)." }, { stepNumber: 2, description: "Confirm the slope at \\(\\alpha\\).", workingLatex: "g'(x) = \\frac{1}{2}\\!\\left(1 - \\frac{10}{x^{2}}\\right), \\qquad g'(\\sqrt{10}) = \\frac{1}{2}(1 - 1) = 0", explanation: "Super-attracting fixed point — quadratic convergence." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\frac{1}{2}\\!\\left(1 + \\frac{10}{1}\\right) = \\frac{11}{2} = 5.5000", explanation: "Large overshoot because \\(x_{0} = 1\\) is far from \\(\\sqrt{10}\\)." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\frac{1}{2}\\!\\left(5.5 + \\frac{10}{5.5}\\right) = \\frac{1}{2}(5.5 + 1.81818\\ldots) \\approx 3.6591", explanation: "Already much closer to \\(\\sqrt{10} \\approx 3.1623\\)." }, { stepNumber: 5, description: "Compute one further iterate to confirm convergence.", workingLatex: "x_{3} = \\frac{1}{2}\\!\\left(3.6591 + \\frac{10}{3.6591}\\right) \\approx 3.1960", explanation: "Already accurate to two decimal places." }, { stepNumber: 6, description: "Sketch \\(y = g(x)\\) with \\(y = x\\).", workingLatex: "", explanation: "The curve drops from \\(+\\infty\\) at \\(x = 0^{+}\\), touches \\(y = x\\) tangentially at \\((\\sqrt{10}, \\sqrt{10})\\), then rises. The staircase from \\(x_{0} = 1\\) overshoots once, then converges rapidly.", diagram: cobwebDiagram((x) => 0.5 * (x + 10 / x), [0.8, 6], [0.8, 6], 1, 3) }, { stepNumber: 7, description: "Conclude.", workingLatex: "", explanation: "Staircase converges quadratically to \\(\\sqrt{10} \\approx 3.1623\\)." } ], finalAnswer: "Staircase converging to \\(\\sqrt{10} \\approx 3.1623\\)." } },
  { id: "y2nm3-061", topicRef: "y2nm3", topicTitle: "Sketching Iteration 61", difficulty: "Challenge", questionText: "A diagram shows the iteration \\(x_{n+1} = g(x_{n})\\) being used to solve \\(f(x) = 0\\). Explain why the points \\((x_{n}, x_{n+1})\\) all lie on the curve \\(y = g(x)\\) but the horizontal transfer to \\(y = x\\) is what converts \\(x_{n+1}\\) into the next input.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "Why the curve \\(y = g(x)\\).", workingLatex: "x_{n+1} = g(x_{n})", explanation: "By definition, the next iterate is the function value at the current iterate; the point \\((x_{n}, g(x_{n})) = (x_{n}, x_{n+1})\\) lies on the curve \\(y = g(x)\\)." }, { stepNumber: 2, description: "Vertical step: read off the output.", workingLatex: "", explanation: "Starting at \\((x_{n}, 0)\\) on the \\(x\\)-axis, draw a vertical segment up to the curve — its endpoint is \\((x_{n}, x_{n+1})\\), whose \\(y\\)-coordinate is the next iterate." }, { stepNumber: 3, description: "Why the line \\(y = x\\).", workingLatex: "", explanation: "To feed \\(x_{n+1}\\) back into \\(g\\), we need it as an \\(x\\)-coordinate, not a \\(y\\)-coordinate. The line \\(y = x\\) has the property that the point \\((x_{n+1}, x_{n+1})\\) lies on it — equal coordinates." }, { stepNumber: 4, description: "Horizontal step: transfer to the diagonal.", workingLatex: "(x_{n}, x_{n+1}) \\to (x_{n+1}, x_{n+1})", explanation: "Move horizontally (constant \\(y\\)) from \\((x_{n}, x_{n+1})\\) until you hit \\(y = x\\); the new point has \\(x\\)-coordinate \\(x_{n+1}\\)." }, { stepNumber: 5, description: "Repeat for the next iterate.", workingLatex: "(x_{n+1}, x_{n+1}) \\to (x_{n+1}, x_{n+2})", explanation: "From the diagonal, a vertical step up to the curve gives \\((x_{n+1}, g(x_{n+1})) = (x_{n+1}, x_{n+2})\\); then another horizontal step continues the cycle.", diagram: cobwebDiagram((x) => 0.5 * x + 0.5, [0, 1.5], [0, 1.5], 0, 4) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "The curve produces the output value; the diagonal recycles it as the next input — two complementary roles that together drive the iteration visually." } ], finalAnswer: "The curve produces the value; the line \\(y = x\\) feeds it back in as the next input." } },
  { id: "y2nm3-062", topicRef: "y2nm3", topicTitle: "Sketching Iteration 62", difficulty: "Challenge", questionText: "Sketch the diagram for \\(x_{n+1} = 4x_{n}(1 - x_{n})\\) starting from \\(x_{0} = 0.2\\). Comment on the behaviour.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["logistic", "chaotic"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = 4x(1 - x)", explanation: "Logistic map at parameter \\(r = 4\\) — the fully chaotic case on \\([0, 1]\\)." }, { stepNumber: 2, description: "Find the fixed points.", workingLatex: "\\alpha = 4\\alpha(1 - \\alpha) \\Rightarrow \\alpha = 0 \\text{ or } \\alpha = \\frac{3}{4} = 0.75", explanation: "" }, { stepNumber: 3, description: "Classify each fixed point.", workingLatex: "g'(x) = 4 - 8x, \\qquad g'(0) = 4, \\quad g'(0.75) = -2", explanation: "Both have \\(|g'| > 1\\), so both fixed points are repelling — no convergence is possible." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 0.2\\).", workingLatex: "x_{1} = 0.64, \\quad x_{2} \\approx 0.9216, \\quad x_{3} \\approx 0.2890, \\quad x_{4} \\approx 0.8219, \\quad x_{5} \\approx 0.5854", explanation: "Values jump unpredictably across \\((0, 1)\\); there is no periodic pattern that emerges and the sequence is sensitive to the starting value." }, { stepNumber: 5, description: "Sketch the parabolic curve with \\(y = x\\).", workingLatex: "", explanation: "Curve peaks at \\((\\tfrac{1}{2}, 1)\\); the cobweb crosses itself many times without settling.", diagram: cobwebDiagram((x) => 4 * x * (1 - x), [0, 1], [0, 1], 0.2, 8) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Both fixed points unstable; the iteration is chaotic — period-doubling cascade has gone to completion, and iterates wander densely through \\([0, 1]\\)." } ], finalAnswer: "Cobweb does not settle; behaviour is chaotic (period-doubling complete)." } },
  { id: "y2nm3-063", topicRef: "y2nm3", topicTitle: "Sketching Iteration 63", difficulty: "Challenge", questionText: "Sketch the staircase for \\(x_{n+1} = \\tfrac{1}{2}(x_{n} + 1)^{1/2}\\) starting from \\(x_{0} = 0.5\\). State the fixed-point equation.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\frac{1}{2}\\sqrt{x + 1}", explanation: "Set \\(g(\\alpha) = \\alpha\\) and square both sides to clear the radical." }, { stepNumber: 2, description: "Derive the fixed-point equation.", workingLatex: "2\\alpha = \\sqrt{\\alpha + 1} \\Rightarrow 4\\alpha^{2} = \\alpha + 1 \\Rightarrow 4\\alpha^{2} - \\alpha - 1 = 0", explanation: "" }, { stepNumber: 3, description: "Apply the quadratic formula.", workingLatex: "\\alpha = \\frac{1 \\pm \\sqrt{1 + 16}}{8} = \\frac{1 \\pm \\sqrt{17}}{8}", explanation: "Take the positive root: \\(\\alpha = \\displaystyle\\frac{1 + \\sqrt{17}}{8} \\approx 0.6404\\)." }, { stepNumber: 4, description: "Differentiate and evaluate at \\(\\alpha\\).", workingLatex: "g'(x) = \\frac{1}{4\\sqrt{x + 1}}, \\qquad g'(\\alpha) = \\frac{1}{4\\sqrt{\\alpha + 1}} = \\frac{1}{8\\alpha} \\approx 0.1952", explanation: "Since \\(\\sqrt{\\alpha+1} = 2\\alpha\\). \\(|g'(\\alpha)| < 1\\) confirms a converging staircase." }, { stepNumber: 5, description: "Compute iterates from \\(x_{0} = 0.5\\).", workingLatex: "x_{1} \\approx 0.6124, \\quad x_{2} \\approx 0.6349, \\quad x_{3} \\approx 0.6393, \\quad x_{4} \\approx 0.6402, \\quad x_{5} \\approx 0.6403", explanation: "Each step closes roughly \\(80\\%\\) of the remaining gap to \\(\\alpha\\)." }, { stepNumber: 6, description: "Sketch the curve \\(y = \\tfrac{1}{2}\\sqrt{x + 1}\\) with \\(y = x\\).", workingLatex: "", explanation: "Slow-rising root curve crosses the diagonal once; staircase from \\(0.5\\) climbs steadily to \\(\\alpha \\approx 0.6404\\).", diagram: cobwebDiagram((x) => 0.5 * Math.sqrt(x + 1), [0, 1], [0, 1], 0.5, 5) } ], finalAnswer: "Staircase converging to \\(\\alpha \\approx 0.6404\\)." } },
  { id: "y2nm3-064", topicRef: "y2nm3", topicTitle: "Sketching Iteration 64", difficulty: "Challenge", questionText: "Sketch the cobweb for \\(x_{n+1} = \\tfrac{3}{x_{n} + 2}\\) starting from \\(x_{0} = 0\\) and state the fixed-point equation.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["cobweb"], workedSolution: { steps: [ { stepNumber: 1, description: "State the iteration function.", workingLatex: "g(x) = \\frac{3}{x + 2}", explanation: "Set \\(g(\\alpha) = \\alpha\\) and clear the denominator." }, { stepNumber: 2, description: "Derive the fixed-point equation.", workingLatex: "\\alpha(\\alpha + 2) = 3 \\Rightarrow \\alpha^{2} + 2\\alpha - 3 = 0 \\Rightarrow (\\alpha - 1)(\\alpha + 3) = 0", explanation: "Roots \\(\\alpha = 1\\) (positive) and \\(\\alpha = -3\\)." }, { stepNumber: 3, description: "Differentiate and evaluate at \\(\\alpha = 1\\).", workingLatex: "g'(x) = -\\frac{3}{(x + 2)^{2}}, \\qquad g'(1) = -\\frac{3}{9} = -\\frac{1}{3}", explanation: "\\(-1 < g'(1) < 0\\) so the fixed point \\(\\alpha = 1\\) attracts via a cobweb." }, { stepNumber: 4, description: "Compute iterates from \\(x_{0} = 0\\).", workingLatex: "x_{1} = \\frac{3}{2} = 1.5000, \\quad x_{2} = \\frac{3}{3.5} \\approx 0.8571, \\quad x_{3} \\approx 1.0500, \\quad x_{4} \\approx 0.9836, \\quad x_{5} \\approx 1.0055", explanation: "Iterates oscillate either side of \\(\\alpha = 1\\), closing in by roughly the factor \\(\\tfrac{1}{3}\\) each step." }, { stepNumber: 5, description: "Sketch the curve \\(y = 3/(x + 2)\\) with \\(y = x\\).", workingLatex: "", explanation: "Decreasing hyperbolic curve crosses the diagonal at \\((1, 1)\\). The cobweb from \\(0\\) spirals neatly into \\((1, 1)\\).", diagram: cobwebDiagram((x) => 3 / (x + 2), [-0.2, 2], [-0.2, 2], 0, 5) }, { stepNumber: 6, description: "Conclude.", workingLatex: "", explanation: "Cobweb converges rapidly to \\(\\alpha = 1\\) (the positive root of \\(\\alpha^{2} + 2\\alpha - 3 = 0\\))." } ], finalAnswer: "Cobweb converging to \\(\\alpha = 1\\)." } },
  { id: "y2nm3-065", topicRef: "y2nm3", topicTitle: "Sketching Iteration 65", difficulty: "Challenge", questionText: "Draw sketches showing each of: (a) a converging staircase, (b) a converging cobweb, (c) a diverging staircase, (d) a diverging cobweb. Label the slope of \\(g\\) at the fixed point in each case.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["summary"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the classification by the slope at the fixed point.", workingLatex: "0 < g'(\\alpha) < 1 \\ \\text{staircase converging}; \\quad -1 < g'(\\alpha) < 0 \\ \\text{cobweb converging}; \\quad g'(\\alpha) > 1 \\ \\text{staircase diverging}; \\quad g'(\\alpha) < -1 \\ \\text{cobweb diverging}.", explanation: "The sign of \\(g'(\\alpha)\\) sets the pattern (staircase vs cobweb); its magnitude vs \\(1\\) decides convergence vs divergence." }, { stepNumber: 2, description: "(a) Converging staircase, \\(g(x) = 0.5x + 0.5\\), \\(\\alpha = 1\\), \\(g'(\\alpha) = 0.5\\).", workingLatex: "", explanation: "Monotone climb to \\((1, 1)\\) from below.", diagram: cobwebDiagram((x) => 0.5 * x + 0.5, [0, 1.5], [0, 1.5], 0, 4) }, { stepNumber: 3, description: "(b) Converging cobweb, \\(g(x) = -0.5x + 1.5\\), \\(\\alpha = 1\\), \\(g'(\\alpha) = -0.5\\).", workingLatex: "", explanation: "Inward spiral around \\((1, 1)\\).", diagram: cobwebDiagram((x) => -0.5 * x + 1.5, [0, 2], [0, 2], 0.2, 5) }, { stepNumber: 4, description: "(c) Diverging staircase, \\(g(x) = 1.5x - 0.5\\), \\(\\alpha = 1\\), \\(g'(\\alpha) = 1.5\\).", workingLatex: "", explanation: "Monotone departure away from \\((1, 1)\\).", diagram: cobwebDiagram((x) => 1.5 * x - 0.5, [0.6, 2.2], [0.6, 2.2], 1.1, 3) }, { stepNumber: 5, description: "(d) Diverging cobweb, \\(g(x) = -1.5x + 2.5\\), \\(\\alpha = 1\\), \\(g'(\\alpha) = -1.5\\).", workingLatex: "", explanation: "Outward spiral around \\((1, 1)\\).", diagram: cobwebDiagram((x) => -1.5 * x + 2.5, [0.3, 1.7], [0.3, 1.7], 1.1, 2) }, { stepNumber: 6, description: "Synthesise the four cases.", workingLatex: "\\text{sign of } g'(\\alpha) \\to \\text{staircase or cobweb}; \\quad |g'(\\alpha)| \\to \\text{converge or diverge}", explanation: "Four pictures, one slope-based rule." } ], finalAnswer: "Four-quadrant summary — the slope determines the behaviour." } },
  { id: "y2nm3-066", topicRef: "y2nm3", topicTitle: "Sketching Iteration 66", difficulty: "Challenge", questionText: "A company models its monthly sales by \\(S_{n+1} = 0.7 S_{n} + 30\\) (thousand pounds). Sketch the staircase diagram from \\(S_{0} = 0\\) and state the long-run equilibrium.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["applied", "staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the iteration in standard form.", workingLatex: "g(S) = 0.7\\,S + 30", explanation: "Linear iteration with retention coefficient \\(0.7\\) and monthly injection \\(£30\\)k." }, { stepNumber: 2, description: "Find the equilibrium by solving \\(g(\\alpha) = \\alpha\\).", workingLatex: "\\alpha = 0.7\\alpha + 30 \\Rightarrow 0.3\\alpha = 30 \\Rightarrow \\alpha = 100", explanation: "Equilibrium sales are \\(£100\\)k per month." }, { stepNumber: 3, description: "Classify the behaviour.", workingLatex: "g'(\\alpha) = 0.7, \\qquad 0 < g'(\\alpha) < 1", explanation: "Staircase converging monotonically — each month sales close \\(30\\%\\) of the remaining gap to the equilibrium." }, { stepNumber: 4, description: "Compute iterates from \\(S_{0} = 0\\).", workingLatex: "S_{1} = 30, \\quad S_{2} = 51, \\quad S_{3} = 65.7, \\quad S_{4} \\approx 75.99, \\quad S_{5} \\approx 83.19", explanation: "Sales rise steadily toward \\(£100\\)k." }, { stepNumber: 5, description: "Sketch the staircase.", workingLatex: "", explanation: "Plot \\(y = 0.7x + 30\\) and \\(y = x\\) on axes (sales in £k). From \\((0, 0)\\) the staircase climbs to \\((100, 100)\\).", diagram: cobwebDiagram((x) => 0.7 * x + 30, [0, 120], [0, 120], 0, 5) }, { stepNumber: 6, description: "Interpret in context.", workingLatex: "", explanation: "Long-run monthly sales settle at \\(£100\\)k regardless of starting value (since \\(|g'| < 1\\))." } ], finalAnswer: "Staircase converging to £100k per month." } },
  { id: "y2nm3-067", topicRef: "y2nm3", topicTitle: "Sketching Iteration 67", difficulty: "Challenge", questionText: "The iteration \\(x_{n+1} = \\tfrac{x_{n}}{2} + \\tfrac{1}{x_{n}}\\) has fixed point \\(\\alpha = \\sqrt{2}\\). Verify using the slope that convergence is fast, and sketch the staircase from \\(x_{0} = 1\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["babylonian", "staircase"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the iteration.", workingLatex: "g(x) = \\frac{x}{2} + \\frac{1}{x}", explanation: "This is the Babylonian iteration for \\(\\sqrt{2}\\): \\(g(x) = \\tfrac{1}{2}(x + 2/x)\\)." }, { stepNumber: 2, description: "Verify \\(\\alpha = \\sqrt{2}\\) is a fixed point.", workingLatex: "g(\\sqrt{2}) = \\frac{\\sqrt{2}}{2} + \\frac{1}{\\sqrt{2}} = \\frac{\\sqrt{2}}{2} + \\frac{\\sqrt{2}}{2} = \\sqrt{2}", explanation: "" }, { stepNumber: 3, description: "Differentiate \\(g\\).", workingLatex: "g'(x) = \\frac{1}{2} - \\frac{1}{x^{2}}", explanation: "" }, { stepNumber: 4, description: "Evaluate \\(g'\\) at \\(\\alpha = \\sqrt{2}\\).", workingLatex: "g'(\\sqrt{2}) = \\frac{1}{2} - \\frac{1}{2} = 0", explanation: "Super-attracting fixed point — the linear convergence factor vanishes, so the error squares each iteration (quadratic convergence)." }, { stepNumber: 5, description: "Compute iterates from \\(x_{0} = 1\\).", workingLatex: "x_{1} = \\frac{1}{2} + 1 = 1.5000, \\quad x_{2} = 0.75 + \\frac{1}{1.5} \\approx 1.4167, \\quad x_{3} \\approx 1.4142", explanation: "\\(\\sqrt{2} \\approx 1.41421356\\): \\(x_{3}\\) is correct to four decimal places after only three steps." }, { stepNumber: 6, description: "Sketch the curve \\(y = x/2 + 1/x\\) with \\(y = x\\).", workingLatex: "", explanation: "Curve dips to a minimum at \\(x = \\sqrt{2}\\), touching the diagonal there tangentially; staircase from \\(x_{0} = 1\\) overshoots, then snaps to \\(\\sqrt{2}\\).", diagram: cobwebDiagram((x) => x / 2 + 1 / x, [0.5, 2], [0.5, 2], 1, 3) }, { stepNumber: 7, description: "Conclude.", workingLatex: "", explanation: "Because \\(g'(\\sqrt{2}) = 0\\), iterates converge quadratically: the number of correct digits roughly doubles each step." } ], finalAnswer: "Staircase converging to \\(\\sqrt{2}\\) very rapidly." } },
  { id: "y2nm3-068", topicRef: "y2nm3", topicTitle: "Sketching Iteration 68", difficulty: "Challenge", questionText: "An iteration \\(x_{n+1} = g(x_{n})\\) has the sketch of \\(y = g(x)\\) shown as a curve steeper than \\(y = x\\) at the fixed point. If we change to the rearrangement \\(y = g^{-1}(x)\\), explain what happens to the slope and whether this new iteration might converge.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the inverse-function derivative rule.", workingLatex: "(g^{-1})'(\\alpha) = \\frac{1}{g'(\\alpha)}", explanation: "If \\(\\alpha\\) is a fixed point of \\(g\\), it is also a fixed point of \\(g^{-1}\\); the slopes are reciprocals at that common point." }, { stepNumber: 2, description: "Apply the criterion \\(|g'(\\alpha)| > 1\\) (steep) implies \\(|(g^{-1})'(\\alpha)| < 1\\).", workingLatex: "|g'(\\alpha)| > 1 \\Rightarrow \\left|\\frac{1}{g'(\\alpha)}\\right| < 1", explanation: "Reciprocation flips magnitudes across \\(1\\): repelling becomes attracting and vice versa." }, { stepNumber: 3, description: "Illustrate with the concrete example \\(g(x) = 2x - 1\\), \\(\\alpha = 1\\).", workingLatex: "g'(\\alpha) = 2 > 1 \\Rightarrow \\text{ diverges}", explanation: "From \\(x_{0} = 1.1\\): \\(x_{1} = 1.2,\\ x_{2} = 1.4,\\ x_{3} = 1.8,\\ \\ldots\\) (escapes).", diagram: cobwebDiagram((x) => 2 * x - 1, [0.6, 2.2], [0.6, 2.2], 1.1, 2) }, { stepNumber: 4, description: "Compute the inverse iteration.", workingLatex: "y = 2x - 1 \\Rightarrow x = \\frac{y + 1}{2} \\Rightarrow g^{-1}(x) = \\frac{x + 1}{2}", explanation: "Same fixed point \\(\\alpha = 1\\), since \\(g^{-1}(1) = 1\\)." }, { stepNumber: 5, description: "Confirm the slope of the new iteration.", workingLatex: "(g^{-1})'(x) = \\frac{1}{2}, \\qquad |g^{-1}{}'(\\alpha)| = \\frac{1}{2} < 1", explanation: "Attracting staircase under \\(g^{-1}\\). From \\(x_{0} = 0\\): \\(x_{1} = 0.5,\\ x_{2} = 0.75,\\ x_{3} = 0.875,\\ \\ldots \\to 1\\).", diagram: cobwebDiagram((x) => (x + 1) / 2, [0, 2], [0, 2], 0, 4) }, { stepNumber: 6, description: "Caveat.", workingLatex: "", explanation: "Inverting only helps when \\(|g'(\\alpha)| > 1\\). If \\(|g'(\\alpha)| = 1\\), the inverse is also borderline; if \\(|g'(\\alpha)| < 1\\) already, the inverse will diverge." } ], finalAnswer: "The inverse has slope \\(< 1\\) in magnitude, so iteration with \\(g^{-1}\\) may now converge." } },
  { id: "y2nm3-069", topicRef: "y2nm3", topicTitle: "Sketching Iteration 69", difficulty: "Challenge", questionText: "Sketch the staircase diagram for the Newton–Raphson iteration applied to \\(f(x) = x^{2} - 5\\), starting from \\(x_{0} = 3\\). What is the slope of \\(g\\) at the fixed point?", marks: 5, examStyle: true, yearCreated: 2026, tags: ["staircase", "newton"], workedSolution: { steps: [ { stepNumber: 1, description: "Write down the Newton–Raphson update.", workingLatex: "x_{n+1} = x_{n} - \\frac{f(x_{n})}{f'(x_{n})}, \\qquad f(x) = x^{2} - 5,\\ f'(x) = 2x", explanation: "" }, { stepNumber: 2, description: "Simplify the iteration function.", workingLatex: "g(x) = x - \\frac{x^{2} - 5}{2x} = \\frac{2x^{2} - (x^{2} - 5)}{2x} = \\frac{x^{2} + 5}{2x} = \\frac{1}{2}\\!\\left(x + \\frac{5}{x}\\right)", explanation: "Recognise the Babylonian iteration for \\(\\sqrt{5}\\)." }, { stepNumber: 3, description: "Identify the fixed point.", workingLatex: "\\alpha = \\sqrt{5} \\approx 2.2361", explanation: "Root of \\(f(x) = 0\\), \\(x > 0\\)." }, { stepNumber: 4, description: "Differentiate and evaluate at \\(\\alpha\\).", workingLatex: "g'(x) = \\frac{1}{2}\\!\\left(1 - \\frac{5}{x^{2}}\\right), \\qquad g'(\\sqrt{5}) = \\frac{1}{2}(1 - 1) = 0", explanation: "Quadratic convergence — the hallmark of Newton–Raphson at a simple root." }, { stepNumber: 5, description: "Compute iterates from \\(x_{0} = 3\\).", workingLatex: "x_{1} = \\frac{1}{2}\\!\\left(3 + \\frac{5}{3}\\right) \\approx 2.3333, \\quad x_{2} \\approx 2.2381, \\quad x_{3} \\approx 2.2361", explanation: "Three iterations bring the error well below \\(10^{-5}\\)." }, { stepNumber: 6, description: "Sketch the staircase.", workingLatex: "", explanation: "Plot \\(y = (x + 5/x)/2\\) and \\(y = x\\). Curve touches the diagonal tangentially at \\((\\sqrt{5}, \\sqrt{5})\\); the staircase from \\(3\\) closes in extremely quickly.", diagram: cobwebDiagram((x) => 0.5 * (x + 5 / x), [1, 3.5], [1, 3.5], 3, 3) }, { stepNumber: 7, description: "Conclude.", workingLatex: "", explanation: "Slope at the fixed point is \\(0\\); convergence to \\(\\sqrt{5}\\) is quadratic." } ], finalAnswer: "Staircase converges rapidly to \\(\\sqrt{5}\\); \\(g'(\\sqrt{5}) = 0\\)." } },
  { id: "y2nm3-070", topicRef: "y2nm3", topicTitle: "Sketching Iteration 70", difficulty: "Challenge", questionText: "Two iterations for solving \\(x^{3} - x - 1 = 0\\) are proposed: (i) \\(x_{n+1} = x_{n}^{3} - 1\\), (ii) \\(x_{n+1} = \\sqrt[3]{x_{n} + 1}\\). Sketch the diagram near the fixed point \\(\\alpha \\approx 1.325\\) for each and state which iteration converges.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["comparison", "classification"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the common fixed point.", workingLatex: "\\alpha^{3} - \\alpha - 1 = 0 \\Rightarrow \\alpha \\approx 1.3247", explanation: "Both rearrangements share this real root: in (i) \\(\\alpha = \\alpha^{3} - 1\\); in (ii) \\(\\alpha = \\sqrt[3]{\\alpha + 1}\\)." }, { stepNumber: 2, description: "Iteration (i): \\(g_{1}(x) = x^{3} - 1\\). Differentiate and evaluate.", workingLatex: "g_{1}'(x) = 3x^{2}, \\qquad g_{1}'(\\alpha) = 3\\alpha^{2} \\approx 3 \\times 1.7548 \\approx 5.265", explanation: "\\(|g_{1}'(\\alpha)| \\gg 1\\) — repelling fixed point, diverging staircase." }, { stepNumber: 3, description: "Iteration (ii): \\(g_{2}(x) = (x + 1)^{1/3}\\). Differentiate and evaluate.", workingLatex: "g_{2}'(x) = \\frac{1}{3}(x + 1)^{-2/3}, \\qquad g_{2}'(\\alpha) = \\frac{1}{3 \\alpha^{2}} \\approx 0.190", explanation: "Used \\((x+1)^{2/3} = ((x+1)^{1/3})^{2} = \\alpha^{2}\\) at the fixed point. \\(|g_{2}'(\\alpha)| < 1\\) — attracting fixed point, converging staircase." }, { stepNumber: 4, description: "Compare and conclude using the convergence criterion.", workingLatex: "|g_{1}'(\\alpha)| \\approx 5.27 > 1 \\ (\\text{diverges}); \\quad |g_{2}'(\\alpha)| \\approx 0.19 < 1 \\ (\\text{converges})", explanation: "Reciprocity: \\(g_{1}\\) and \\(g_{2}\\) are inverses, and \\(g_{2}'(\\alpha) = 1/g_{1}'(\\alpha)\\)." }, { stepNumber: 5, description: "Compute iterates of (ii) from \\(x_{0} = 1\\).", workingLatex: "x_{1} \\approx 1.2599, \\quad x_{2} \\approx 1.3123, \\quad x_{3} \\approx 1.3224, \\quad x_{4} \\approx 1.3243", explanation: "Iterates climb steadily toward \\(\\alpha \\approx 1.3247\\)." }, { stepNumber: 6, description: "Sketch the converging staircase for (ii).", workingLatex: "", explanation: "Curve \\(y = (x+1)^{1/3}\\) crosses \\(y = x\\) at \\(\\alpha\\); from \\(x_{0} = 1\\) the staircase rises smoothly to the fixed point.", diagram: cobwebDiagram((x) => Math.cbrt(x + 1), [1, 1.5], [1, 1.5], 1, 4) }, { stepNumber: 7, description: "State the final answer.", workingLatex: "", explanation: "Iteration (ii) converges to \\(\\alpha \\approx 1.3247\\); iteration (i) diverges away from it." } ], finalAnswer: "Only iteration (ii) converges; (i) diverges." } },
];
